111: function openCreate(){showPanel('CREATE SERVER',`<div class="form-grid"><label class="field">SERVER NAME<input id="server-name" value="Old Quarter Classic"></label><label class="field">MAP<select id="map-select"><option>Old Quarter</option><option>Dustworks</option><option>Foundry</option><option>Harbor District</option></select></label><label class="field">GAME MODE<select id="mode-select"><option>Bomb Defusal</option><option>Hostage Rescue</option><option>Team Deathmatch</option><option>Free For All</option><option>Practice</option></select></label><label class="field">MAX PLAYERS<select id="max-players"><option>10</option><option>16</option><option>24</option><option>32</option></select></label><label class="field">BOTS<select id="bot-count"><option>8</option><option>4</option><option>6</option><option>10</option><option>0</option></select></label><label class="field">BOT SKILL<select id="bot-skill"><option>Normal</option><option>Easy</option><option>Hard</option><option>Expert</option></select></label><label class="field">ROUND TIME<select id="round-time"><option value="120">2:00 minutes</option><option value="180">3:00 minutes</option><option value="90">1:30 minutes</option></select></label><label class="field">STARTING CASH<select id="start-cash"><option value="800">$800</option><option value="16000">$16,000</option><option value="0">$0</option></select></label><label class="field full">VISIBILITY<select id="server-visibility"><option>Private LAN match</option><option>Public (available on this network)</option></select></label></div><div class="panel-actions"><button data-close>Cancel</button><button id="launch-match">START GAME</button></div>`);
