export function clamp(v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; }
export function lerp(a, b, t) { return a + (b - a) * t; }
export function damp(current, target, lambda, dt) {
  return lerp(current, target, 1 - Math.exp(-lambda * dt));
}
export function formatTime(seconds) {
  const s = Math.max(0, Math.ceil(seconds));
  return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
}

// Procedural, self-contained texture and material library. No external assets required.
import * as THREE from 'three';

function rng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

function canvasTexture(size, painter, repeat = 1) {
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');
  painter(ctx, size);
  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeat, repeat);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

function grain(ctx, size, rand, count, rgba) {
  for (let i = 0; i < count; i++) {
    ctx.fillStyle = rgba(rand);
    const w = 1 + rand() * 5;
    ctx.fillRect(rand() * size, rand() * size, w, w * (0.4 + rand()));
  }
}

function plasterPainter(base, stain) {
  return (ctx, s) => {
    const rand = rng(17);
    ctx.fillStyle = base; ctx.fillRect(0, 0, s, s);
    for (let i = 0; i < 120; i++) {
      const r = 4 + rand() * 34;
      ctx.fillStyle = `rgba(${stain},${0.02 + rand() * 0.055})`;
      ctx.beginPath(); ctx.arc(rand() * s, rand() * s, r, 0, Math.PI * 2); ctx.fill();
    }
    // Hairline cracks
    ctx.strokeStyle = 'rgba(45,38,28,.20)'; ctx.lineWidth = 1;
    for (let i = 0; i < 7; i++) {
      let x = rand() * s, y = rand() * s;
      ctx.beginPath(); ctx.moveTo(x, y);
      for (let j = 0; j < 7; j++) { x += (rand() - 0.5) * 18; y += rand() * 14; ctx.lineTo(x, y); }
      ctx.stroke();
    }
    grain(ctx, s, rand, 2600, (r) => `rgba(60,50,36,${0.03 + r() * 0.09})`);
  };
}

function brickPainter(base, mortar) {
  return (ctx, s) => {
    const rand = rng(31);
    ctx.fillStyle = mortar; ctx.fillRect(0, 0, s, s);
    const bh = s / 12, bw = s / 6;
    for (let row = 0; row < 12; row++) {
      const off = row % 2 ? -bw / 2 : 0;
      for (let col = -1; col < 7; col++) {
        const x = col * bw + off + 2, y = row * bh + 2;
        const shade = 0.75 + rand() * 0.35;
        ctx.fillStyle = shadeColor(base, shade);
        ctx.fillRect(x, y, bw - 4, bh - 4);
        ctx.fillStyle = `rgba(255,240,210,${0.02 + rand() * 0.05})`;
        ctx.fillRect(x + 2, y + 2, bw - 8, 2);
      }
    }
    grain(ctx, s, rand, 1600, (r) => `rgba(30,20,14,${0.03 + r() * 0.1})`);
  };
}

function concretePainter(base) {
  return (ctx, s) => {
    const rand = rng(73);
    ctx.fillStyle = base; ctx.fillRect(0, 0, s, s);
    for (let i = 0; i < 80; i++) {
      ctx.fillStyle = `rgba(250,250,245,${rand() * 0.055})`;
      ctx.beginPath(); ctx.arc(rand() * s, rand() * s, 4 + rand() * 20, 0, Math.PI * 2); ctx.fill();
    }
    for (let i = 0; i < 30; i++) {
      ctx.strokeStyle = `rgba(30,30,28,${0.06 + rand() * 0.12})`;
      ctx.lineWidth = 0.7 + rand();
      ctx.beginPath(); ctx.moveTo(rand() * s, rand() * s);
      ctx.lineTo(rand() * s, rand() * s); ctx.stroke();
    }
    grain(ctx, s, rand, 3000, (r) => `rgba(30,30,27,${0.02 + r() * 0.09})`);
  };
}

function cobblePainter(ctx, s) {
  const rand = rng(101);
  ctx.fillStyle = '#544f43'; ctx.fillRect(0, 0, s, s);
  const n = 10;
  const cell = s / n;
  for (let row = 0; row < n; row++) {
    const off = row % 2 ? cell / 2 : 0;
    for (let col = -1; col < n + 1; col++) {
      const x = col * cell + off + 2, y = row * cell + 2;
      const shade = 0.7 + rand() * 0.45;
      ctx.fillStyle = shadeColor('#8b8270', shade);
      ctx.beginPath();
      ctx.roundRect(x, y, cell - 4, cell - 4, 5 + rand() * 4);
      ctx.fill();
      ctx.strokeStyle = 'rgba(30,28,22,.25)'; ctx.stroke();
      ctx.fillStyle = `rgba(255,246,220,${rand() * 0.06})`;
      ctx.fillRect(x + 5, y + 4, cell * 0.45, 3);
    }
  }
  grain(ctx, s, rand, 1500, (r) => `rgba(25,23,18,${0.03 + r() * 0.08})`);
}

function asphaltPainter(ctx, s) {
  const rand = rng(211);
  ctx.fillStyle = '#4b4b47'; ctx.fillRect(0, 0, s, s);
  grain(ctx, s, rand, 9000, (r) => `rgba(${20 + r() * 80},${20 + r() * 80},${20 + r() * 70},${0.05 + r() * 0.28})`);
  for (let i = 0; i < 4; i++) {
    ctx.strokeStyle = 'rgba(25,25,22,.5)'; ctx.lineWidth = 1.4;
    let x = rand() * s, y = rand() * s; ctx.beginPath(); ctx.moveTo(x, y);
    for (let j = 0; j < 9; j++) { x += (rand() - 0.5) * 28; y += (rand() - 0.5) * 28; ctx.lineTo(x, y); }
    ctx.stroke();
  }
}

function woodPainter(base) {
  return (ctx, s) => {
    const rand = rng(307);
    ctx.fillStyle = base; ctx.fillRect(0, 0, s, s);
    const planks = 6, pw = s / planks;
    for (let p = 0; p < planks; p++) {
      ctx.fillStyle = shadeColor(base, 0.78 + rand() * 0.4);
      ctx.fillRect(p * pw + 1, 0, pw - 2, s);
      ctx.fillStyle = 'rgba(25,16,9,.5)';
      ctx.fillRect(p * pw, 0, 1.5, s);
      for (let i = 0; i < 14; i++) {
        ctx.strokeStyle = `rgba(40,26,14,${0.06 + rand() * 0.13})`;
        ctx.lineWidth = 1;
        ctx.beginPath();
        const x = p * pw + 4 + rand() * (pw - 9);
        ctx.moveTo(x, rand() * s);
        ctx.bezierCurveTo(x + rand() * 5, s * 0.3, x - rand() * 5, s * 0.6, x + rand() * 4, rand() * s);
        ctx.stroke();
      }
    }
    grain(ctx, s, rand, 900, (r) => `rgba(20,12,6,${r() * 0.12})`);
  };
}

function metalPainter(ctx, s) {
  const rand = rng(401);
  ctx.fillStyle = '#5c625f'; ctx.fillRect(0, 0, s, s);
  for (let i = 0; i < 26; i++) {
    ctx.fillStyle = `rgba(${190 + rand() * 40},${195 + rand() * 40},${190 + rand() * 40},${rand() * 0.09})`;
    ctx.fillRect(0, rand() * s, s, 1 + rand() * 3);
  }
  for (let i = 0; i < 25; i++) {
    const x = rand() * s, y = rand() * s;
    ctx.fillStyle = 'rgba(35,32,27,.35)';
    ctx.beginPath(); ctx.arc(x, y, 1.2 + rand() * 2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = 'rgba(200,200,190,.22)'; ctx.beginPath(); ctx.arc(x - 1, y - 1, 1, 0, Math.PI * 2); ctx.fill();
  }
  grain(ctx, s, rand, 2200, (r) => `rgba(30,28,25,${r() * 0.08})`);
}

function rustPainter(ctx, s) {
  const rand = rng(509);
  ctx.fillStyle = '#6c5340'; ctx.fillRect(0, 0, s, s);
  for (let i = 0; i < 180; i++) {
    ctx.fillStyle = `rgba(${90 + rand() * 90},${45 + rand() * 40},${20 + rand() * 25},${0.1 + rand() * 0.35})`;
    ctx.beginPath(); ctx.arc(rand() * s, rand() * s, 2 + rand() * 16, 0, Math.PI * 2); ctx.fill();
  }
  grain(ctx, s, rand, 2400, (r) => `rgba(45,25,12,${r() * 0.2})`);
}

function roofPainter(ctx, s) {
  const rand = rng(607);
  ctx.fillStyle = '#6c4938'; ctx.fillRect(0, 0, s, s);
  const rows = 10, rh = s / rows;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < 10; c++) {
      const x = c * (s / 10) + (r % 2 ? s / 20 : 0);
      ctx.fillStyle = shadeColor('#9a6048', 0.7 + rand() * 0.45);
      ctx.beginPath(); ctx.roundRect(x, r * rh, s / 10 - 2, rh - 2, 3); ctx.fill();
    }
  }
  grain(ctx, s, rand, 1000, (r) => `rgba(30,18,10,${r() * 0.12})`);
}

function hazardPainter(ctx, s) {
  const rand = rng(709);
  ctx.fillStyle = '#c9a73c'; ctx.fillRect(0, 0, s, s);
  ctx.fillStyle = '#25241f';
  for (let i = -s; i < s * 2; i += 48) {
    ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i + 24, 0); ctx.lineTo(i + 24 - s, s); ctx.lineTo(i - s, s); ctx.closePath(); ctx.fill();
  }
  grain(ctx, s, rand, 700, (r) => `rgba(20,18,12,${r() * 0.15})`);
}

function sandPainter(ctx, s) {
  const rand = rng(811);
  ctx.fillStyle = '#a69677'; ctx.fillRect(0, 0, s, s);
  grain(ctx, s, rand, 7000, (r) => `rgba(${70 + r() * 90},${60 + r() * 80},${40 + r() * 60},${r() * 0.26})`);
}

function tilePainter(ctx, s) {
  const rand = rng(907);
  ctx.fillStyle = '#777568'; ctx.fillRect(0, 0, s, s);
  const n = 4, cell = s / n;
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    ctx.fillStyle = shadeColor('#9b988a', 0.86 + rand() * 0.22);
    ctx.fillRect(x * cell + 2, y * cell + 2, cell - 4, cell - 4);
  }
  grain(ctx, s, rand, 1000, (r) => `rgba(30,30,25,${r() * 0.08})`);
}

function shadeColor(hex, factor) {
  const c = new THREE.Color(hex);
  c.multiplyScalar(factor);
  return `rgb(${Math.min(255, c.r * 255) | 0},${Math.min(255, c.g * 255) | 0},${Math.min(255, c.b * 255) | 0})`;
}

export class MaterialLibrary {
  constructor(renderer) {
    this.renderer = renderer;
    this.textures = {};
    this.materials = {};
    this.build();
  }

  build() {
    const T = this.textures;
    T.plaster = canvasTexture(256, plasterPainter('#b8a67e', '74,62,44'), 2.2);
    T.plasterWarm = canvasTexture(256, plasterPainter('#c0a77d', '92,70,45'), 2.2);
    T.plasterCool = canvasTexture(256, plasterPainter('#9fa093', '50,53,45'), 2.4);
    T.brick = canvasTexture(256, brickPainter('#8e624c', '#766b59'), 2.1);
    T.brickDark = canvasTexture(256, brickPainter('#705041', '#5d5547'), 2.0);
    T.concrete = canvasTexture(256, concretePainter('#85857b'), 2.6);
    T.concreteDark = canvasTexture(256, concretePainter('#65675f'), 2.8);
    T.cobble = canvasTexture(256, cobblePainter, 6.5);
    T.asphalt = canvasTexture(256, asphaltPainter, 10);
    T.wood = canvasTexture(256, woodPainter('#765536'), 2.0);
    T.woodDark = canvasTexture(256, woodPainter('#59412b'), 1.8);
    T.metal = canvasTexture(256, metalPainter, 2.2);
    T.metalDark = canvasTexture(256, metalPainter, 3.2);
    T.rust = canvasTexture(256, rustPainter, 2.2);
    T.roof = canvasTexture(256, roofPainter, 3.2);
    T.hazard = canvasTexture(256, hazardPainter, 2.4);
    T.sand = canvasTexture(256, sandPainter, 7);
    T.tile = canvasTexture(256, tilePainter, 3.0);

    // Window texture: dark glass with a dim sky reflection.
    T.window = canvasTexture(256, (ctx, s) => {
      const g = ctx.createLinearGradient(0, 0, s, s);
      g.addColorStop(0, '#52666a'); g.addColorStop(0.45, '#26363a'); g.addColorStop(0.55, '#1b292d'); g.addColorStop(1, '#43565c');
      ctx.fillStyle = g; ctx.fillRect(0, 0, s, s);
      ctx.fillStyle = 'rgba(220,230,220,.13)';
      ctx.fillRect(s * 0.16, 0, s * 0.1, s);
      ctx.fillStyle = 'rgba(255,240,210,.07)';
      ctx.fillRect(s * 0.55, 0, s * 0.05, s);
      ctx.fillStyle = 'rgba(10,14,14,.45)'; ctx.fillRect(0, s * 0.48, s, 5);
      ctx.fillRect(s * 0.48, 0, 5, s);
    }, 1);

    T.windowLit = canvasTexture(256, (ctx, s) => {
      const g = ctx.createLinearGradient(0, 0, 0, s);
      g.addColorStop(0, '#d5b779'); g.addColorStop(1, '#7b5c35');
      ctx.fillStyle = g; ctx.fillRect(0, 0, s, s);
      ctx.fillStyle = 'rgba(40,30,20,.55)'; ctx.fillRect(s * 0.47, 0, 6, s); ctx.fillRect(0, s * 0.47, s, 6);
    }, 1);

    const std = (name, map, opts = {}) => {
      const m = new THREE.MeshStandardMaterial({ map, color: 0xffffff, ...opts });
      if (map) m.map.repeat.set(map.repeat.x, map.repeat.y);
      this.materials[name] = m;
      return m;
    };

    std('plaster', T.plaster, { roughness: 0.96 });
    std('plasterWarm', T.plasterWarm, { roughness: 0.96 });
    std('plasterCool', T.plasterCool, { roughness: 0.95 });
    std('brick', T.brick, { roughness: 0.95 });
    std('brickDark', T.brickDark, { roughness: 0.95 });
    std('concrete', T.concrete, { roughness: 0.98 });
    std('concreteDark', T.concreteDark, { roughness: 0.97 });
    std('cobble', T.cobble, { roughness: 0.94 });
    std('asphalt', T.asphalt, { roughness: 0.98 });
    std('wood', T.wood, { roughness: 0.84 });
    std('woodDark', T.woodDark, { roughness: 0.88 });
    std('metal', T.metal, { roughness: 0.55, metalness: 0.45 });
    std('metalDark', T.metalDark, { roughness: 0.62, metalness: 0.35 });
    std('rust', T.rust, { roughness: 0.9, metalness: 0.15 });
    std('roof', T.roof, { roughness: 0.93 });
    std('hazard', T.hazard, { roughness: 0.8 });
    std('sand', T.sand, { roughness: 1 });
    std('tile', T.tile, { roughness: 0.7 });
    std('window', T.window, { roughness: 0.18, metalness: 0.4 });
    std('windowLit', T.windowLit, { roughness: 0.4, emissive: 0x3b2a10, emissiveIntensity: 1.4 });

    const mats = this.materials;
    mats.dark = new THREE.MeshStandardMaterial({ color: 0x282a25, roughness: 0.85 });
    mats.black = new THREE.MeshStandardMaterial({ color: 0x171916, roughness: 0.9 });
    mats.white = new THREE.MeshStandardMaterial({ color: 0xc9c7b5, roughness: 0.85 });
    mats.cloth = new THREE.MeshStandardMaterial({ color: 0x5d5b4c, roughness: 1 });
    mats.canvasRed = new THREE.MeshStandardMaterial({ color: 0x8e4a37, roughness: 1, side: THREE.DoubleSide });
    mats.canvasCream = new THREE.MeshStandardMaterial({ color: 0xb9a782, roughness: 1, side: THREE.DoubleSide });
    mats.canvasGreen = new THREE.MeshStandardMaterial({ color: 0x51614b, roughness: 1, side: THREE.DoubleSide });
    mats.water = new THREE.MeshStandardMaterial({ color: 0x3b5b59, roughness: 0.18, metalness: 0.55, transparent: true, opacity: 0.82 });
    mats.leaf = new THREE.MeshStandardMaterial({ color: 0x4c5d3b, roughness: 1 });
    mats.leafDark = new THREE.MeshStandardMaterial({ color: 0x37462e, roughness: 1 });
    mats.skin = new THREE.MeshStandardMaterial({ color: 0xb08a6a, roughness: 0.85 });
    mats.skinDark = new THREE.MeshStandardMaterial({ color: 0x8a6549, roughness: 0.85 });
    mats.ctCloth = new THREE.MeshStandardMaterial({ color: 0x3d4b4b, roughness: 0.93 });
    mats.ctVest = new THREE.MeshStandardMaterial({ color: 0x293433, roughness: 0.8 });
    mats.tCloth = new THREE.MeshStandardMaterial({ color: 0x75654a, roughness: 0.95 });
    mats.tVest = new THREE.MeshStandardMaterial({ color: 0x4f4433, roughness: 0.82 });
    mats.helmet = new THREE.MeshStandardMaterial({ color: 0x36423f, roughness: 0.68, metalness: 0.15 });
    mats.helmetT = new THREE.MeshStandardMaterial({ color: 0x5a4e3a, roughness: 0.85 });
    mats.boots = new THREE.MeshStandardMaterial({ color: 0x24241f, roughness: 0.9 });
    mats.weapon = new THREE.MeshStandardMaterial({ color: 0x2e322e, roughness: 0.5, metalness: 0.45 });
    mats.weaponWood = new THREE.MeshStandardMaterial({ color: 0x60472f, roughness: 0.8 });
    mats.glassGreen = new THREE.MeshStandardMaterial({ color: 0x2e4644, roughness: 0.15, metalness: 0.5, transparent: true, opacity: 0.7 });
    mats.lamp = new THREE.MeshStandardMaterial({ color: 0xffe2a1, emissive: 0xffc766, emissiveIntensity: 2.4, roughness: 0.4 });
    mats.redLamp = new THREE.MeshStandardMaterial({ color: 0x8f2f24, emissive: 0xb8301e, emissiveIntensity: 1.4, roughness: 0.5 });
    mats.orange = new THREE.MeshStandardMaterial({ color: 0xcf6d2a, roughness: 0.78 });
    mats.yellow = new THREE.MeshStandardMaterial({ color: 0xc6a63f, roughness: 0.7 });
    mats.blue = new THREE.MeshStandardMaterial({ color: 0x3f5f79, roughness: 0.8 });
    mats.green = new THREE.MeshStandardMaterial({ color: 0x4f6448, roughness: 0.85 });
    mats.red = new THREE.MeshStandardMaterial({ color: 0x7e3f32, roughness: 0.8 });
    mats.metalBright = new THREE.MeshStandardMaterial({ color: 0x8a8d83, roughness: 0.4, metalness: 0.7 });
    mats.wire = new THREE.MeshBasicMaterial({ color: 0x25251f });

    // Add subtle bump detail using the color maps (cheap and stable).
    for (const [name, m] of Object.entries(mats)) {
      if (m.map && ['plaster', 'plasterWarm', 'plasterCool', 'brick', 'brickDark', 'concrete', 'concreteDark', 'cobble', 'asphalt', 'wood', 'woodDark', 'roof', 'metal', 'metalDark', 'rust', 'sand', 'tile'].includes(name)) {
        m.bumpMap = m.map;
        m.bumpScale = name === 'brick' || name === 'brickDark' ? 0.05 : 0.022;
      }
    }
  }

  get(name) {
    return this.materials[name] || this.materials.concrete;
  }

  setAnisotropy(amount) {
    for (const t of Object.values(this.textures)) {
      t.anisotropy = amount;
      t.needsUpdate = true;
    }
  }
}

// Deterministic collision helpers. Maps are made of analytic AABBs so they are cheap
// to query for movement, line of sight and hit-scan fire.
import * as THREE from 'three';

export function circleOverlapsAABB(x, z, r, c) {
  const cx = x < c.minX ? c.minX : x > c.maxX ? c.maxX : x;
  const cz = z < c.minZ ? c.minZ : z > c.maxZ ? c.maxZ : z;
  const dx = x - cx, dz = z - cz;
  return dx * dx + dz * dz < r * r;
}

export function pointInAABB(x, z, r, c) {
  return x + r > c.minX && x - r < c.maxX && z + r > c.minZ && z - r < c.maxZ;
}

// Ground/support height under a circle. Only surfaces within step reach are considered.
export function supportHeight(world, x, z, feetY, radius = 0.32, step = 0.42) {
  let best = 0;
  for (const c of world.colliders) {
    if (c.maxY > feetY + step + 0.02) continue;
    if (c.maxY <= best) continue;
    if (pointInAABB(x, z, radius * 0.72, c)) best = c.maxY;
  }
  return best;
}

export function collidesAt(world, x, z, feetY, height = 1.7, radius = 0.34, step = 0.42) {
  for (const c of world.colliders) {
    if (c.maxY <= feetY + step + 0.01) continue; // can step onto / stand on it
    if (c.minY >= feetY + height - 0.02) continue; // overhead clearance
    if (pointInAABB(x, z, radius, c)) return true;
  }
  return false;
}

export function isSpawnFree(world, x, z, radius = 0.4) {
  if (!world || !world.colliders) return false;
  return !collidesAt(world, x, z, 0, 1.7, radius, 0.12);
}

// Move a capsule horizontally with axis separation and sub-stepping. Returns actual dx/dz.
export function moveHorizontal(world, pos, dx, dz, height = 1.7, radius = 0.34, step = 0.42) {
  const startX = pos.x, startZ = pos.z;
  const dist = Math.hypot(dx, dz);
  const steps = Math.max(1, Math.ceil(dist / 0.12));
  const sx = dx / steps, sz = dz / steps;
  for (let i = 0; i < steps; i++) {
    const nx = pos.x + sx;
    if (!collidesAt(world, nx, pos.z, pos.y, height, radius, step)) pos.x = nx;
    else if (!collidesAt(world, pos.x + sx * 0.35, pos.z, pos.y, height, radius, step)) pos.x += sx * 0.35;
    const nz = pos.z + sz;
    if (!collidesAt(world, pos.x, nz, pos.y, height, radius, step)) pos.z = nz;
    else if (!collidesAt(world, pos.x, pos.z + sz * 0.35, pos.y, height, radius, step)) pos.z += sz * 0.35;
  }
  return { dx: pos.x - startX, dz: pos.z - startZ };
}

// Segment vs AABB. Returns entry distance and normal.
export function rayAABB(ox, oy, oz, dx, dy, dz, maxDist, c) {
  let tmin = 0, tmax = maxDist;
  let nx = 0, ny = 0, nz = 0;
  // X slab
  if (Math.abs(dx) < 1e-8) {
    if (ox < c.minX || ox > c.maxX) return null;
  } else {
    let t1 = (c.minX - ox) / dx, t2 = (c.maxX - ox) / dx;
    let sign = -1;
    if (t1 > t2) { [t1, t2] = [t2, t1]; sign = 1; }
    if (t1 > tmin) { tmin = t1; nx = sign; ny = 0; nz = 0; }
    if (t2 < tmax) tmax = t2;
    if (tmin > tmax) return null;
  }
  // Y slab
  if (Math.abs(dy) < 1e-8) {
    if (oy < c.minY || oy > c.maxY) return null;
  } else {
    let t1 = (c.minY - oy) / dy, t2 = (c.maxY - oy) / dy;
    let sign = -1;
    if (t1 > t2) { [t1, t2] = [t2, t1]; sign = 1; }
    if (t1 > tmin) { tmin = t1; nx = 0; ny = sign; nz = 0; }
    if (t2 < tmax) tmax = t2;
    if (tmin > tmax) return null;
  }
  // Z slab
  if (Math.abs(dz) < 1e-8) {
    if (oz < c.minZ || oz > c.maxZ) return null;
  } else {
    let t1 = (c.minZ - oz) / dz, t2 = (c.maxZ - oz) / dz;
    let sign = -1;
    if (t1 > t2) { [t1, t2] = [t2, t1]; sign = 1; }
    if (t1 > tmin) { tmin = t1; nx = 0; ny = 0; nz = sign; }
    if (t2 < tmax) tmax = t2;
    if (tmin > tmax) return null;
  }
  if (tmin < 0) return null;
  return { distance: tmin, normal: new THREE.Vector3(nx, ny, nz) };
}

export function raycastWorld(world, origin, dir, maxDist) {
  let hit = null;
  for (const c of world.colliders) {
    const r = rayAABB(origin.x, origin.y, origin.z, dir.x, dir.y, dir.z, maxDist, c);
    if (r && (!hit || r.distance < hit.distance)) {
      hit = { ...r, collider: c };
    }
  }
  return hit;
}

export function rayBlocked(world, from, to, padding = 0.02) {
  const dx = to.x - from.x, dy = to.y - from.y, dz = to.z - from.z;
  const dist = Math.hypot(dx, dy, dz);
  if (dist < 1e-5) return false;
  const inv = 1 / dist;
  const hit = raycastWorld(world, from, { x: dx * inv, y: dy * inv, z: dz * inv }, dist - padding);
  return !!hit;
}

// 2D line-of-walk check used to build navigation links.
export function segmentBlocked(world, a, b, radius = 0.36) {
  const dx = b.x - a.x, dz = b.z - a.z;
  const len = Math.hypot(dx, dz);
  const steps = Math.max(1, Math.ceil(len / 0.5));
  for (let i = 1; i <= steps; i++) {
    const t = i / steps;
    const x = a.x + dx * t, z = a.z + dz * t;
    const y = a.y + (b.y - a.y) * t;
    if (collidesAt(world, x, z, y, 1.7, radius, 0.5)) return true;
  }
  return false;
}

// Ray vs sphere. Returns distance or null.
export function raySphere(ox, oy, oz, dx, dy, dz, cx, cy, cz, radius) {
  const lx = cx - ox, ly = cy - oy, lz = cz - oz;
  const tca = lx * dx + ly * dy + lz * dz;
  if (tca < 0) return null;
  const d2 = lx * lx + ly * ly + lz * lz - tca * tca;
  const r2 = radius * radius;
  if (d2 > r2) return null;
  const thc = Math.sqrt(r2 - d2);
  const t0 = tca - thc, t1 = tca + thc;
  if (t1 < 0) return null;
  return t0 >= 0 ? { distance: t0, point: new THREE.Vector3(ox + dx * t0, oy + dy * t0, oz + dz * t0) } : { distance: t1, point: new THREE.Vector3(ox + dx * t1, oy + dy * t1, oz + dz * t1) };
}

// Navigation graph, grid sampling and A* pathfinding for bots.
import { isSpawnFree, segmentBlocked, supportHeight } from './physics.js';

export class NavGraph {
  constructor(nodes = []) {
    this.nodes = nodes;
    this.nextId = nodes.length;
  }

  static build(world, { spacing = 4.6, margin = 2.4, maxLink = 8.2 } = {}) {
    const nodes = [];
    const { minX, maxX, minZ, maxZ } = world.bounds;
    for (let x = minX + margin; x <= maxX - margin; x += spacing) {
      for (let z = minZ + margin; z <= maxZ - margin; z += spacing) {
        const jitterX = ((Math.round(z * 7) % 5) - 2) * 0.16;
        const jitterZ = ((Math.round(x * 5) % 5) - 2) * 0.16;
        const px = x + jitterX, pz = z + jitterZ;
        if (!isSpawnFree(world, px, pz, 0.52)) continue;
        const y = supportHeight(world, px, pz, 0, 0.38, 0.42);
        nodes.push({ id: 0, x: px, y, z: pz, neighbors: [] });
      }
    }

    // Explicit nodes supplied by maps are appended (used for raised platforms).
    for (const n of world.extraNavNodes || []) {
      if (!isSpawnFree(world, n.x, n.z, 0.45) && !n.force) continue;
      nodes.push({ id: 0, x: n.x, y: n.y ?? supportHeight(world, n.x, n.z, n.y ?? 0, .38, .5), z: n.z, neighbors: [] });
    }

    nodes.forEach((n, i) => { n.id = i; });

    for (let i = 0; i < nodes.length; i++) {
      const a = nodes[i];
      for (let j = i + 1; j < nodes.length; j++) {
        const b = nodes[j];
        const d = Math.hypot(b.x - a.x, b.z - a.z);
        if (d > maxLink || d < 0.5) continue;
        if (Math.abs(a.y - b.y) > 0.65) continue;
        if (segmentBlocked(world, a, b, 0.4)) continue;
        a.neighbors.push({ node: b, cost: d });
        b.neighbors.push({ node: a, cost: d });
      }
    }

    // Keep only the largest connected component so every path is usable.
    const seen = new Set();
    let best = [];
    for (const n of nodes) {
      if (seen.has(n.id)) continue;
      const stack = [n]; const comp = []; seen.add(n.id);
      while (stack.length) {
        const cur = stack.pop(); comp.push(cur);
        for (const e of cur.neighbors) if (!seen.has(e.node.id)) { seen.add(e.node.id); stack.push(e.node); }
      }
      if (comp.length > best.length) best = comp;
    }

    if (best.length) {
      const keep = new Set(best.map(n => n.id));
      const filtered = best.map(n => ({
        ...n,
        neighbors: n.neighbors.filter(e => keep.has(e.node.id)),
      }));
      filtered.forEach((n, i) => { n.id = i; });
      // Rebuild neighbor references after re-indexing.
      const byOld = new Map(best.map((n, i) => [n.id, filtered[i]]));
      for (const n of filtered) {
        n.neighbors = n.neighbors.map(e => {
          const oldNode = best.find(x => x.id === e.node.id) || e.node;
          const target = byOld.get(oldNode.id);
          return target ? { node: target, cost: e.cost } : null;
        }).filter(Boolean);
      }
      return new NavGraph(filtered);
    }
    return new NavGraph(nodes);
  }

  nearest(pos, maxCheck = 12) {
    let best = null, bestD = Infinity;
    for (const n of this.nodes) {
      const dx = n.x - pos.x, dz = n.z - pos.z;
      const d = dx * dx + dz * dz;
      if (d < bestD) { bestD = d; best = n; }
    }
    return best;
  }

  // Find a reachable node close to a point, checking the final approach.
  nearestReachable(world, pos, radius = 1.1) {
    const sorted = [...this.nodes].sort((a, b) =>
      (a.x - pos.x) ** 2 + (a.z - pos.z) ** 2 - ((b.x - pos.x) ** 2 + (b.z - pos.z) ** 2));
    for (let i = 0; i < Math.min(sorted.length, 18); i++) {
      const n = sorted[i];
      if (Math.abs(n.y - (pos.y ?? n.y)) > 1.6) continue;
      if (!segmentBlocked(world, { x: pos.x, y: pos.y ?? n.y, z: pos.z }, n, 0.34)) return n;
    }
    return sorted[0] || null;
  }

  findPath(startPos, endPos) {
    if (!this.nodes.length) return [];
    const start = this.nearest(startPos);
    const end = this.nearest(endPos);
    if (!start || !end) return [];
    if (start === end) return [end];

    const open = [start];
    const came = new Map();
    const gScore = new Map([[start.id, 0]]);
    const fScore = new Map([[start.id, Math.hypot(end.x - start.x, end.z - start.z)]]);
    const closed = new Set();

    while (open.length) {
      let bestIdx = 0;
      for (let i = 1; i < open.length; i++) {
        if ((fScore.get(open[i].id) ?? Infinity) < (fScore.get(open[bestIdx].id) ?? Infinity)) bestIdx = i;
      }
      const current = open.splice(bestIdx, 1)[0];
      if (current === end) {
        const path = [current];
        let cur = current;
        while (came.has(cur.id)) { cur = came.get(cur.id); path.unshift(cur); }
        return path;
      }
      closed.add(current.id);
      for (const edge of current.neighbors) {
        const neighbor = edge.node;
        if (closed.has(neighbor.id)) continue;
        const tentative = (gScore.get(current.id) ?? Infinity) + edge.cost;
        if (tentative >= (gScore.get(neighbor.id) ?? Infinity)) continue;
        came.set(neighbor.id, current);
        gScore.set(neighbor.id, tentative);
        fScore.set(neighbor.id, tentative + Math.hypot(end.x - neighbor.x, end.z - neighbor.z));
        if (!open.includes(neighbor)) open.push(neighbor);
      }
    }
    return [];
  }

  randomNode(rng = Math.random) {
    return this.nodes.length ? this.nodes[Math.floor(rng() * this.nodes.length)] : null;
  }
}

// Shared map-building toolkit. Produces optimized box/cylinder geometry, analytic
// colliders, navigation data, team spawn points and a top-down radar footprint.
import * as THREE from 'three';
import { NavGraph } from '../nav.js';
import { supportHeight } from '../physics.js';

const boxGeo = new THREE.BoxGeometry(1, 1, 1);
const planeGeo = new THREE.PlaneGeometry(1, 1);
const cylGeo = new Map();
const sphereGeo = new Map();
const torusGeo = new Map();

function cylinderGeometry(segments = 10) {
  if (!cylGeo.has(segments)) cylGeo.set(segments, new THREE.CylinderGeometry(0.5, 0.5, 1, segments));
  return cylGeo.get(segments);
}
function sphereGeometry(segments = 8) {
  if (!sphereGeo.has(segments)) sphereGeo.set(segments, new THREE.SphereGeometry(0.5, segments, Math.max(4, segments - 2)));
  return sphereGeo.get(segments);
}
function torusGeometry(radius = 0.5, tube = 0.05, segments = 10) {
  const key = `${radius}:${tube}:${segments}`;
  if (!torusGeo.has(key)) torusGeo.set(key, new THREE.TorusGeometry(radius, tube, 5, segments));
  return torusGeo.get(key);
}

export class MapBuilder {
  constructor(scene, materials, id) {
    this.scene = scene;
    this.materials = materials;
    this.id = id;
    this.root = new THREE.Group();
    this.root.name = `map:${id}`;
    scene.add(this.root);
    this.colliders = [];
    this.spawns = { CT: [], T: [] };
    this.extraNavNodes = [];
    this.lights = [];
    this.bounds = { minX: -36, maxX: 36, minZ: -36, maxZ: 36 };
    this.floorMesh = null;
    this.sky = null;
    this._signCache = new Map();
  }

  mat(name) { return this.materials.get(name); }

  addMesh(mesh, opts = {}) {
    mesh.castShadow = opts.cast !== false;
    mesh.receiveShadow = opts.receive !== false;
    this.root.add(mesh);
    return mesh;
  }

  addCollider(minX, maxX, minY, maxY, minZ, maxZ, material = 'concrete', walkable = false) {
    this.colliders.push({ minX, maxX, minY, maxY, minZ, maxZ, material, walkable });
  }

  box(x, y, z, w, h, d, material, opts = {}) {
    const m = new THREE.Mesh(boxGeo, typeof material === 'string' ? this.mat(material) : material);
    m.position.set(x, y, z);
    m.scale.set(w, h, d);
    if (opts.rotY) m.rotation.y = opts.rotY;
    if (opts.rotX) m.rotation.x = opts.rotX;
    if (opts.rotZ) m.rotation.z = opts.rotZ;
    this.addMesh(m, opts);
    if (opts.solid !== false) {
      if (opts.rotY && Math.abs(Math.sin(opts.rotY)) > 0.05) {
        const sw = Math.abs(w * Math.cos(opts.rotY)) + Math.abs(d * Math.sin(opts.rotY));
        const sd = Math.abs(w * Math.sin(opts.rotY)) + Math.abs(d * Math.cos(opts.rotY));
        this.addCollider(x - sw / 2, x + sw / 2, y - h / 2, y + h / 2, z - sd / 2, z + sd / 2, opts.materialKey || 'concrete', !!opts.walkable);
      } else {
        this.addCollider(x - w / 2, x + w / 2, y - h / 2, y + h / 2, z - d / 2, z + d / 2, opts.materialKey || 'concrete', !!opts.walkable);
      }
    }
    return m;
  }

  boxBetween(x1, x2, y, z1, z2, h, material, opts = {}) {
    const w = Math.abs(x2 - x1), d = Math.abs(z2 - z1);
    return this.box((x1 + x2) / 2, y, (z1 + z2) / 2, Math.max(0.05, w), h, Math.max(0.05, d), material, opts);
  }

  cylinder(x, y, z, radius, height, material, opts = {}) {
    const m = new THREE.Mesh(cylinderGeometry(opts.segments || 10), typeof material === 'string' ? this.mat(material) : material);
    m.position.set(x, y, z);
    m.scale.set(radius * 2, height, radius * 2);
    if (opts.rotX) m.rotation.x = opts.rotX;
    if (opts.rotZ) m.rotation.z = opts.rotZ;
    this.addMesh(m, opts);
    if (opts.solid !== false) {
      this.addCollider(x - radius, x + radius, y - height / 2, y + height / 2, z - radius, z + radius, opts.materialKey || 'metal', false);
    }
    return m;
  }

  sphere(x, y, z, radius, material, opts = {}) {
    const m = new THREE.Mesh(sphereGeometry(opts.segments || 8), typeof material === 'string' ? this.mat(material) : material);
    m.position.set(x, y, z);
    m.scale.setScalar(radius * 2);
    this.addMesh(m, opts);
    return m;
  }

  torus(x, y, z, radius, tube, material, opts = {}) {
    const m = new THREE.Mesh(torusGeometry(radius, tube, opts.segments || 12), typeof material === 'string' ? this.mat(material) : material);
    m.position.set(x, y, z);
    if (opts.rotX) m.rotation.x = opts.rotX;
    if (opts.rotY) m.rotation.y = opts.rotY;
    if (opts.rotZ) m.rotation.z = opts.rotZ;
    this.addMesh(m, opts);
    return m;
  }

  ground(material, size = 160, y = 0, repeat = 1) {
    const m = new THREE.Mesh(planeGeo, typeof material === 'string' ? this.mat(material) : material);
    m.rotation.x = -Math.PI / 2;
    m.position.y = y;
    m.scale.set(size, size, 1);
    m.receiveShadow = true;
    m.castShadow = false;
    this.root.add(m);
    if (!this.floorMesh) this.floorMesh = m;
    return m;
  }

  surface(x, z, w, d, y, material, opts = {}) {
    return this.box(x, y - 0.03, z, w, 0.06, d, material, { solid: true, walkable: true, cast: false, ...opts });
  }

  addLight(color, intensity, distance, x, y, z, options = {}) {
    const light = new THREE.PointLight(color, intensity, distance, options.decay ?? 1.6);
    light.position.set(x, y, z);
    light.castShadow = !!options.castShadow;
    if (light.castShadow) {
      light.shadow.mapSize.set(512, 512);
      light.shadow.bias = -0.002;
    }
    this.root.add(light);
    this.lights.push(light);
    return light;
  }

  sky(top, horizon, bottom, sunColor, sunDir = new THREE.Vector3(-0.45, 0.28, -0.85)) {
    const geo = new THREE.SphereGeometry(320, 24, 16);
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      uniforms: {
        topColor: { value: new THREE.Color(top) },
        horizonColor: { value: new THREE.Color(horizon) },
        bottomColor: { value: new THREE.Color(bottom) },
        sunColor: { value: new THREE.Color(sunColor) },
        sunDir: { value: sunDir.clone().normalize() },
      },
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        varying vec3 vDir;
        uniform vec3 topColor;
        uniform vec3 horizonColor;
        uniform vec3 bottomColor;
        uniform vec3 sunColor;
        uniform vec3 sunDir;
        void main() {
          float h = vDir.y;
          vec3 col = mix(horizonColor, topColor, smoothstep(0.0, 0.65, h));
          col = mix(bottomColor, col, smoothstep(-0.25, 0.02, h));
          float sun = pow(max(dot(vDir, sunDir), 0.0), 380.0);
          float glow = pow(max(dot(vDir, sunDir), 0.0), 8.0) * 0.20;
          col += sunColor * (sun * 1.8 + glow);
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    });
    this.sky = new THREE.Mesh(geo, mat);
    this.sky.frustumCulled = false;
    this.root.add(this.sky);
    return this.sky;
  }

  building({ x, z, w, d, h, material = 'plaster', roof = 'roof', style = 'classic', faces = ['n', 's', 'e', 'w'], sign, litChance = 0.22, balconyFace = null }) {
    const wall = this.box(x, h / 2, z, w, h, d, material, { materialKey: 'concrete' });
    // Plinth, cornice and roof cap.
    this.box(x, 0.28, z, w + 0.35, 0.56, d + 0.35, 'concreteDark', { cast: false, materialKey: 'concrete' });
    this.box(x, h + 0.12, z, w + 0.7, 0.28, d + 0.7, style === 'industrial' ? 'metalDark' : 'concrete', { cast: false });
    this.box(x, h + 0.28, z, w + 0.25, 0.12, d + 0.25, roof, { cast: false });
    // Roof silhouette / parapet.
    if (style !== 'industrial') {
      for (const [dx, dz, ww, dd] of [[0, -d / 2, w, 0.28], [0, d / 2, w, 0.28], [-w / 2, 0, 0.28, d], [w / 2, 0, 0.28, d]]) {
        this.box(x + dx, h + 0.45, z + dz, ww, 0.5, dd, material, { cast: false });
      }
    }
    const faceDefs = {
      n: { axis: 'x', span: w, fixed: z - d / 2, normal: -1, rot: Math.PI },
      s: { axis: 'x', span: w, fixed: z + d / 2, normal: 1, rot: 0 },
      w: { axis: 'z', span: d, fixed: x - w / 2, normal: -1, rot: -Math.PI / 2 },
      e: { axis: 'z', span: d, fixed: x + w / 2, normal: 1, rot: Math.PI / 2 },
    };
    for (const face of faces) {
      const f = faceDefs[face];
      if (!f) continue;
      const count = Math.max(1, Math.floor((f.span - 1.4) / 3.0));
      const spacing = f.span / count;
      const floors = Math.max(1, Math.floor((h - 1.4) / 3.0));
      for (let fl = 0; fl < floors; fl++) {
        const wy = 2.15 + fl * 3.0;
        if (wy + 1.2 > h) break;
        for (let i = 0; i < count; i++) {
          const off = -f.span / 2 + spacing * (i + 0.5);
          const lit = Math.random() < litChance;
          if (f.axis === 'x') {
            this.window(x + off, wy, f.fixed + f.normal * 0.055, 1.16, 1.62, f.rot, lit);
          } else {
            this.window(f.fixed + f.normal * 0.055, wy, z + off, 1.16, 1.62, f.rot, lit);
          }
        }
      }
      // Door / shopfront on the first face.
      if (face === faces[0]) {
        const dx = f.axis === 'x' ? x : f.fixed + f.normal * 0.06;
        const dz = f.axis === 'x' ? f.fixed + f.normal * 0.06 : z;
        this.door(dx, dz, f.rot, style, sign);
      }
      if (style !== 'industrial') {
        // Downpipe at one corner of each facade
        const px = f.axis === 'x' ? x - f.span / 2 + 0.65 : f.fixed + f.normal * 0.18;
        const pz = f.axis === 'x' ? f.fixed + f.normal * 0.18 : z - f.span / 2 + 0.65;
        this.cylinder(px, h / 2, pz, 0.075, h - 0.4, 'metalDark', { segments: 6, solid: false, cast: false });
      }
    }
    if (balconyFace) this.balcony(x, z, w, d, h, balconyFace);
    if (style === 'classic') this.roofDetails(x, z, w, d, h);
    return wall;
  }

  window(x, y, z, w, h, rotY, lit) {
    this.box(x, y, z, w, h, 0.07, lit ? 'windowLit' : 'window', { solid: false, cast: false, rotY });
    const frame = 'metalDark';
    this.box(x, y, z, w + 0.18, 0.08, 0.1, frame, { solid: false, cast: false, rotY });
    this.box(x, y - h / 2 - 0.06, z, w + 0.3, 0.12, 0.22, 'concrete', { solid: false, cast: false, rotY });
    this.box(x, y + h / 2 + 0.04, z, w + 0.26, 0.1, 0.18, 'concrete', { solid: false, cast: false, rotY });
    // Cross bars
    this.box(x, y, z, 0.055, h, 0.1, frame, { solid: false, cast: false, rotY });
    this.box(x, y, z, w, 0.055, 0.1, frame, { solid: false, cast: false, rotY });
  }

  door(x, z, rotY, style, sign) {
    const dw = style === 'industrial' ? 3.2 : 1.28;
    const dh = style === 'industrial' ? 3.8 : 2.35;
    this.box(x, dh / 2, z, dw, dh, 0.12, style === 'industrial' ? 'metalDark' : 'woodDark', { solid: false, cast: false, rotY });
    this.box(x, dh / 2 + 0.04, z, dw - 0.24, dh - 0.2, 0.15, style === 'industrial' ? 'metal' : 'wood', { solid: false, cast: false, rotY });
    this.box(x, dh + 0.12, z, dw + 0.55, 0.2, 0.22, 'concrete', { solid: false, cast: false, rotY });
    this.box(x, 0.12, z, dw + 0.6, 0.24, 0.7, 'concrete', { solid: false, cast: false, rotY, walkable: false });
    if (sign) this.sign(sign, x, dh + 0.65, z, 2.8, 0.62, rotY);
    if (style !== 'industrial') {
      // Awning
      this.box(x, dh + 0.42, z + (Math.abs(Math.sin(rotY)) < 0.5 ? (Math.cos(rotY) > 0 ? 0.65 : -0.65) : 0),
        2.4, 0.09, 1.2, 'canvasCream', { solid: false, cast: true, rotX: 0.18, rotY, receive: true });
    }
  }

  balcony(x, z, w, d, h, face) {
    const y = Math.min(h - 1.7, 3.35);
    if (face === 'n' || face === 's') {
      const zz = z + (face === 'n' ? -d / 2 - 0.7 : d / 2 + 0.7);
      this.box(x, y, zz, w * 0.56, 0.18, 1.5, 'concrete', { solid: false, cast: true });
      for (let i = -3; i <= 3; i++) {
        this.box(x + i * w * 0.075, y + 0.52, zz + (face === 'n' ? -0.7 : 0.7), 0.055, 1.0, 0.055, 'metalDark', { solid: false, cast: false });
      }
      this.box(x, y + 1.02, zz + (face === 'n' ? -0.7 : 0.7), w * 0.56, 0.07, 0.08, 'metalDark', { solid: false, cast: false });
      for (let i = -1; i <= 1; i++) this.box(x + i * 1.1, y + 0.24, zz, 0.36, 0.3, 0.3, 'green', { solid: false, cast: false });
    } else {
      const xx = x + (face === 'w' ? -w / 2 - 0.7 : w / 2 + 0.7);
      this.box(xx, y, z, 1.5, 0.18, d * 0.56, 'concrete', { solid: false, cast: true });
      for (let i = -3; i <= 3; i++) {
        this.box(xx + (face === 'w' ? -0.7 : 0.7), y + 0.52, z + i * d * 0.075, 0.055, 1.0, 0.055, 'metalDark', { solid: false, cast: false });
      }
      this.box(xx + (face === 'w' ? -0.7 : 0.7), y + 1.02, z, d * 0.56, 0.07, 0.08, 'metalDark', { solid: false, cast: false });
    }
  }

  roofDetails(x, z, w, d, h) {
    // Chimneys and roof clutter give the skyline a believable silhouette.
    this.box(x - w * 0.28, h + 1.05, z + d * 0.2, 0.8, 1.7, 0.8, 'brickDark', { cast: true });
    this.box(x - w * 0.28, h + 1.95, z + d * 0.2, 1.05, 0.16, 1.05, 'concrete', { cast: false });
    if (Math.random() > 0.35) {
      this.box(x + w * 0.25, h + 0.75, z - d * 0.2, 1.1, 1.0, 0.75, 'metalDark', { cast: true });
      this.box(x + w * 0.25, h + 0.38, z - d * 0.2, 1.2, 0.22, 0.85, 'metal', { cast: false });
    }
    this.box(x + w * 0.12, h + 0.52, z + d * 0.18, 1.4, 0.22, 0.22, 'metalDark', { solid: false, cast: false });
    this.box(x + w * 0.12, h + 0.75, z + d * 0.18, 0.08, 0.6, 0.08, 'metalDark', { solid: false, cast: false });
  }

  sign(text, x, y, z, w = 2.4, h = 0.6, rotY = 0) {
    let tex = this._signCache.get(text);
    if (!tex) {
      const c = document.createElement('canvas'); c.width = 256; c.height = 64;
      const ctx = c.getContext('2d');
      ctx.fillStyle = '#2b2a24'; ctx.fillRect(0, 0, 256, 64);
      ctx.strokeStyle = '#8f7a50'; ctx.lineWidth = 4; ctx.strokeRect(2, 2, 252, 60);
      ctx.fillStyle = '#d8bd7b'; ctx.font = 'bold 29px monospace'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.letterSpacing = '2px';
      ctx.fillText(text.toUpperCase(), 128, 35);
      tex = new THREE.CanvasTexture(c);
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.anisotropy = 4;
      this._signCache.set(text, tex);
    }
    const m = new THREE.Mesh(planeGeo, new THREE.MeshStandardMaterial({ map: tex, roughness: 0.6, emissive: 0x221b0e, emissiveIntensity: 0.4 }));
    m.position.set(x, y, z); m.scale.set(w, h, 1); m.rotation.y = rotY;
    this.addMesh(m, { cast: false, receive: false });
    return m;
  }

  crate(x, z, size = 1.1, y = null, rotY = 0) {
    const baseY = y ?? size / 2;
    this.box(x, baseY, z, size, size, size, 'wood', { rotY, materialKey: 'wood' });
    this.box(x, baseY + size * 0.32, z, size + 0.04, 0.1, size + 0.04, 'woodDark', { solid: false, cast: false, rotY });
    this.box(x, baseY - size * 0.32, z, size + 0.04, 0.1, size + 0.04, 'woodDark', { solid: false, cast: false, rotY });
    this.box(x - size * 0.3, baseY, z, 0.09, size * 0.9, size + 0.02, 'woodDark', { solid: false, cast: false, rotY });
    this.box(x + size * 0.3, baseY, z, 0.09, size * 0.9, size + 0.02, 'woodDark', { solid: false, cast: false, rotY });
  }

  barrel(x, z, color = 'rust', y = 0) {
    this.cylinder(x, y + 0.62, z, 0.43, 1.24, color, { segments: 12, cast: true });
    this.cylinder(x, y + 1.25, z, 0.44, 0.06, 'metalDark', { segments: 12, cast: false });
    this.cylinder(x, y + 0.2, z, 0.445, 0.05, 'metalDark', { segments: 12, cast: false });
    this.cylinder(x, y + 1.12, z, 0.445, 0.05, 'metalDark', { segments: 12, cast: false });
  }

  sandbag(x, z, rows = 3, length = 2.4, rotY = 0) {
    for (let r = 0; r < rows; r++) {
      for (let i = 0; i < Math.ceil(length / 0.55); i++) {
        const off = -length / 2 + 0.3 + i * 0.55 + (r % 2 ? 0.15 : 0);
        const dx = Math.cos(rotY) * off, dz = Math.sin(rotY) * off;
        this.box(x + dx, 0.22 + r * 0.34, z + dz, 0.64, 0.36, 0.42, 'sand', { rotY, cast: true, materialKey: 'sand' });
      }
    }
  }

  streetLamp(x, z, color = 0xffd28a, height = 4.4) {
    this.cylinder(x, 0.16, z, 0.34, 0.32, 'concreteDark', { segments: 10 });
    this.cylinder(x, height / 2, z, 0.055, height, 'metalDark', { segments: 6, solid: false, cast: false });
    this.box(x, height, z, 0.08, 0.08, 0.8, 'metalDark', { solid: false, cast: false });
    this.box(x, height - 0.16, z - 0.36, 0.34, 0.18, 0.42, 'metalDark', { solid: false });
    this.box(x, height - 0.28, z - 0.36, 0.22, 0.22, 0.28, 'lamp', { solid: false, cast: false });
    this.addLight(color, 7.5, 11, x, height - 0.3, z - 0.36);
  }

  cables(points, sag = 0.7) {
    const curve = new THREE.CatmullRomCurve3(points.map(p => new THREE.Vector3(p[0], p[1], p[2])));
    const geo = new THREE.TubeGeometry(curve, 28, 0.025, 4, false);
    const mesh = new THREE.Mesh(geo, this.mat('wire'));
    mesh.castShadow = false;
    this.root.add(mesh);
    // A couple of dangling lamps.
    for (const t of [0.32, 0.66]) {
      const p = curve.getPoint(t);
      this.cylinder(p.x, p.y - 0.25, p.z, 0.025, 0.5, 'metalDark', { segments: 4, solid: false, cast: false });
      this.box(p.x, p.y - 0.55, p.z, 0.2, 0.25, 0.2, 'lamp', { solid: false, cast: false });
    }
  }

  planter(x, z, size = 1.3) {
    this.box(x, 0.34, z, size, 0.68, size, 'concrete', { materialKey: 'concrete' });
    this.box(x, 0.68, z, size - 0.15, 0.08, size - 0.15, 'woodDark', { solid: false, cast: false });
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * Math.PI * 2;
      this.box(x + Math.cos(a) * size * 0.18, 1.05, z + Math.sin(a) * size * 0.18, 0.42, 0.65, 0.42, i % 2 ? 'leaf' : 'leafDark', { solid: false, cast: true, rotY: a, rotZ: 0.18 });
    }
  }

  marketStall(x, z, rotY = 0, color = 'canvasRed') {
    // Table, legs and a sloped canvas roof.
    this.box(x, 0.78, z, 3.0, 0.14, 1.3, 'wood', { rotY });
    this.box(x, 0.38, z, 2.7, 0.7, 1.0, 'woodDark', { solid: false, cast: false, rotY });
    for (const dx of [-1.35, 1.35]) for (const dz of [-0.55, 0.55]) {
      this.box(x + Math.cos(rotY) * dx - Math.sin(rotY) * dz, 1.55, z + Math.sin(rotY) * dx + Math.cos(rotY) * dz, 0.08, 2.4, 0.08, 'metalDark', { solid: false, cast: false, rotY });
    }
    this.box(x, 2.72, z, 3.3, 0.09, 2.2, color, { solid: false, cast: true, rotX: 0.12, rotY, receive: true });
    this.box(x, 2.55, z, 3.15, 0.16, 0.5, color, { solid: false, cast: false, rotY });
    for (let i = -1; i <= 1; i++) this.crate(x + i * 0.84, z + 0.15, 0.42, 1.08, rotY);
  }

  arch(x, z, rotY = 0, width = 4.2, height = 3.8) {
    const half = width / 2;
    for (const s of [-1, 1]) {
      const dx = Math.cos(rotY) * half * s;
      const dz = Math.sin(rotY) * half * s;
      this.box(x + dx, height / 2, z + dz, 0.72, height, 0.9, 'brick', { rotY });
      this.box(x + dx, height + 0.1, z + dz, 0.95, 0.25, 1.1, 'concrete', { rotY, cast: false });
    }
    const curve = new THREE.Mesh(new THREE.TorusGeometry(half, 0.35, 6, 16, Math.PI), this.mat('brick'));
    curve.position.set(x, height, z);
    curve.rotation.z = Math.PI;
    curve.rotation.y = rotY;
    curve.castShadow = true;
    this.root.add(curve);
    // Colliders for the supports only.
    for (const s of [-1, 1]) {
      const dx = Math.cos(rotY) * half * s, dz = Math.sin(rotY) * half * s;
      this.addCollider(x + dx - 0.55, x + dx + 0.55, 0, height, z + dz - 0.55, z + dz + 0.55, 'brick', false);
    }
  }

  fountain(x, z, radius = 2.8) {
    // Octagonal basin with water and a central pedestal.
    const basin = this.cylinder(x, 0.38, z, radius, 0.76, 'concrete', { segments: 8, materialKey: 'concrete' });
    basin.receiveShadow = true;
    this.cylinder(x, 0.7, z, radius - 0.22, 0.1, 'water', { segments: 16, solid: false, cast: false });
    this.cylinder(x, 4.5, z, 0.34, 1.35, 'concrete', { segments: 8, cast: false });
    this.cylinder(x, 3.2, z, 0.86, 0.24, 'concrete', { segments: 10, solid: false, cast: true });
    this.cylinder(x, 3.75, z, 0.24, 1.1, 'concrete', { segments: 8, solid: false, cast: false });
    this.sphere(x, 5.25, z, 0.22, 'metalDark', { segments: 8 });
    // Water jets represented as thin transparent columns.
    for (let i = 0; i < 6; i++) {
      const a = (i / 6) * Math.PI * 2;
      this.cylinder(x + Math.cos(a) * 1.1, 3.45, z + Math.sin(a) * 1.1, 0.035, 0.55, 'water', { segments: 5, solid: false, cast: false });
    }
    this.addLight(0x8fb7bd, 3.2, 9, x, 2.7, z);
  }

  rubbleField(minX, maxX, minZ, maxZ, count = 30, materials = ['concrete', 'brickDark', 'sand']) {
    const geo = new THREE.DodecahedronGeometry(1, 0);
    const inst = new THREE.InstancedMesh(geo, this.mat(materials[0]), count);
    const dummy = new THREE.Object3D();
    for (let i = 0; i < count; i++) {
      const x = minX + Math.random() * (maxX - minX);
      const z = minZ + Math.random() * (maxZ - minZ);
      dummy.position.set(x, Math.random() * 0.15, z);
      dummy.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
      dummy.scale.set(0.25 + Math.random() * 0.65, 0.12 + Math.random() * 0.32, 0.25 + Math.random() * 0.65);
      dummy.updateMatrix();
      inst.setMatrixAt(i, dummy.matrix);
    }
    inst.receiveShadow = true;
    inst.castShadow = false;
    this.root.add(inst);
  }

  finalize({ navSpacing = 4.7, fog } = {}) {
    const graph = NavGraph.build(this, { spacing: navSpacing });
    this.nav = graph;
    // Radar footprint from tall solid geometry.
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = 256;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#202a22'; ctx.fillRect(0, 0, 256, 256);
    const b = this.bounds;
    const sx = 256 / (b.maxX - b.minX), sz = 256 / (b.maxZ - b.minZ);
    ctx.fillStyle = '#455045';
    for (const c of this.colliders) {
      if (c.maxY < 1.5) continue;
      const x = (c.minX - b.minX) * sx, y = (c.minZ - b.minZ) * sz;
      ctx.fillRect(x, y, Math.max(1, (c.maxX - c.minX) * sx), Math.max(1, (c.maxZ - c.minZ) * sz));
    }
    ctx.strokeStyle = '#77816d'; ctx.lineWidth = 2; ctx.strokeRect(1, 1, 254, 254);
    this.radarTexture = canvas;
    return this;
  }

  spawn(team, x, z) {
    const y = supportHeight({ colliders: this.colliders }, x, z, 0.3, 0.3, 0.6);
    this.spawns[team].push(new THREE.Vector3(x, y, z));
    return this;
  }

  spawnAny(x, z) {
    const y = supportHeight({ colliders: this.colliders }, x, z, 0.3, 0.3, 0.6);
    this.spawns.CT.push(new THREE.Vector3(x, y, z));
    this.spawns.T.push(new THREE.Vector3(x, y, z));
  }
}

