// Map-aware bot combatant: perception, finite-state behaviour, A* navigation and
// difficulty-scaled aiming. Bots only fire at targets they can actually see.
import * as THREE from 'three';
import { DIFFICULTIES, PLAYER, clamp, damp } from './config.js';
import { moveHorizontal, rayBlocked, supportHeight } from './physics.js';
import { Soldier } from './characters.js';

const TMP_A = new THREE.Vector3();
const TMP_B = new THREE.Vector3();
const TMP_C = new THREE.Vector3();

function angleDiff(a, b) {
  return Math.atan2(Math.sin(b - a), Math.cos(b - a));
}

export class Bot {
  constructor({ team, name, materials, scene, difficulty = 'Normal', index = 0 }) {
    this.team = team;
    this.name = name;
    this.index = index;
    this.isPlayer = false;
    this.skillName = difficulty;
    this.skill = DIFFICULTIES[difficulty] || DIFFICULTIES.Normal;
    this.variation = 0.82 + Math.random() * 0.36;
    this.accuracyVariation = 0.9 + Math.random() * 0.2;
    this.maxHealth = Math.round(this.skill.health * (0.92 + Math.random() * 0.16));
    this.health = this.maxHealth;
    this.alive = true;
    this.respawnTimer = 0;
    this.pos = new THREE.Vector3();
    this.vel = new THREE.Vector3();
    this.yaw = 0;
    this.pitch = 0;
    this.state = 'patrol';
    this.stateTimer = 0;
    this.target = null;
    this.targetVisible = false;
    this.lastSeen = new THREE.Vector3();
    this.lastSeenTimer = 0;
    this.reactionTimer = 0;
    this.fireCooldown = 0;
    this.burstLeft = 0;
    this.burstPause = 0;
    this.ammo = 30;
    this.reloadT = 0;
    this.thinkTimer = Math.random() * 0.15;
    this.path = [];
    this.pathIndex = 0;
    this.goal = null;
    this.goalType = 'patrol';
    this.repathTimer = 0;
    this.strafeDir = Math.random() > 0.5 ? 1 : -1;
    this.strafeTimer = 1 + Math.random() * 2;
    this.stuckTimer = 0;
    this.stuckCount = 0;
    this.lastStuckPos = new THREE.Vector3();
    this.investigateTimer = 0;
    this.idleTimer = Math.random();
    this.deathHideTimer = 0;
    this.soldier = new Soldier(team, name, materials, index);
    scene.add(this.soldier.group);
    this.group = this.soldier.group;
    this.group.position.copy(this.pos);
    this.contactCooldown = 0;
    this.firstSeen = 0;
  }

  reset(spawn, yaw = 0) {
    this.pos.copy(spawn);
    this.health = this.maxHealth;
    this.alive = true;
    this.respawnTimer = 0;
    this.yaw = yaw;
    this.pitch = 0;
    this.target = null;
    this.targetVisible = false;
    this.state = 'patrol';
    this.stateTimer = 0;
    this.path = [];
    this.pathIndex = 0;
    this.goal = null;
    this.reactionTimer = 0;
    this.fireCooldown = 0.4 + Math.random() * 0.8;
    this.burstLeft = 0;
    this.burstPause = 0;
    this.ammo = 30;
    this.reloadT = 0;
    this.investigateTimer = 0;
    this.idleTimer = Math.random() * 1.3;
    this.stuckCount = 0;
    this.lastStuckPos.copy(this.pos);
    this.soldier.revive();
    this.group.position.copy(this.pos);
    this.group.rotation.y = yaw;
  }

  die() {
    this.alive = false;
    this.target = null;
    this.state = 'dead';
    this.path = [];
    this.deathHideTimer = 1.7;
    this.soldier.dead = false;
    this.soldier.update(0, { dead: true });
  }

  hear(pos) {
    if (!this.alive || this.state === 'engage') return;
    if (Math.random() < 0.35) return;
    this.lastSeen.copy(pos);
    this.lastSeenTimer = Math.max(this.lastSeenTimer, 2.6);
    if (this.state !== 'investigate' && this.state !== 'pursue') {
      this.state = 'investigate';
      this.stateTimer = 0;
      this.path = [];
      this.goal = pos.clone();
      this.goalType = 'investigate';
    }
  }

  reportContact(targetPos) {
    if (!this.alive || this.state === 'engage') return;
    this.lastSeen.copy(targetPos);
    this.lastSeenTimer = Math.max(this.lastSeenTimer, 3.2);
  }

  getEyeWorld() {
    return new THREE.Vector3(this.pos.x, this.pos.y + 1.62, this.pos.z);
  }

  getHitboxes() {
    return this.soldier.getHitboxes();
  }

  update(dt, game) {
    if (!this.alive) {
      this.deathHideTimer -= dt;
      if (this.deathHideTimer <= 0) this.soldier.group.visible = false;
      else this.soldier.update(dt, { dead: true });
      this.respawnTimer = Math.max(0, this.respawnTimer - dt);
      return;
    }

    this.thinkTimer -= dt;
    this.contactCooldown = Math.max(0, this.contactCooldown - dt);
    this.fireCooldown = Math.max(0, this.fireCooldown - dt);
    this.reactionTimer = Math.max(0, this.reactionTimer - dt);
    this.stateTimer += dt;
    this.strafeTimer -= dt;
    if (this.strafeTimer <= 0) {
      this.strafeDir *= -1;
      this.strafeTimer = 1.1 + Math.random() * 2.4;
    }
    if (this.reloadT > 0) {
      this.reloadT -= dt;
      if (this.reloadT <= 0) this.ammo = 30;
    }

    if (this.thinkTimer <= 0) {
      this.thinkTimer = 0.16 + Math.random() * 0.1;
      this.perceive(game);
    }

    this.updateBehaviour(dt, game);

    // Animation state follows the tactical state.
    const speed = Math.hypot(this.vel.x, this.vel.z);
    this.soldier.update(dt, {
      speed,
      aiming: this.state === 'engage' || this.state === 'investigate',
      crouching: this.state === 'engage' && this.health < this.maxHealth * 0.35 && Math.random() < 0.01,
      dead: false,
    });
    this.group.position.copy(this.pos);
    this.group.rotation.y = this.yaw;
  }

  perceive(game) {
    const eye = this.getEyeWorld();
    const forward = new THREE.Vector3(Math.sin(this.yaw), 0, Math.cos(this.yaw));
    const halfFov = Math.cos((this.skill.fov * Math.PI / 180) / 2);
    let best = null, bestScore = Infinity;
    let visibleAny = false;

    for (const other of game.combatants()) {
      if (other === this || !other.alive) continue;
      if (!game.isEnemy(this, other)) continue;
      const otherEye = other.isPlayer ? other.eyePosition() : other.getEyeWorld();
      const dx = otherEye.x - eye.x, dz = otherEye.z - eye.z;
      const dist = Math.hypot(dx, dz);
      if (dist > this.skill.sight) continue;
      const flat = new THREE.Vector3(dx, 0, dz).normalize();
      const inFov = forward.dot(flat) > halfFov;
      if (!inFov && dist > 4.2) continue;
      const chest = other.isPlayer
        ? new THREE.Vector3(other.pos.x, other.pos.y + 1.25, other.pos.z)
        : new THREE.Vector3(other.pos.x, other.pos.y + 1.3, other.pos.z);
      if (rayBlocked(game.world, eye, chest, 0.08)) continue;
      // Target selection: closer and already-engaged targets score better.
      let score = dist;
      if (other === this.target) score -= 6;
      if (other.isPlayer) score -= 2.5;
      if (other.health < 35) score -= 2;
      if (score < bestScore) { bestScore = score; best = other; visibleAny = true; }
    }

    if (best) {
      if (this.target !== best) {
        this.reactionTimer = this.skill.reaction[0] + Math.random() * (this.skill.reaction[1] - this.skill.reaction[0]);
        this.firstSeen = 0;
      }
      this.target = best;
      this.targetVisible = true;
      this.lastSeen.set(best.pos.x, best.pos.y + 1.2, best.pos.z);
      this.lastSeenTimer = 3.8;
      if (this.contactCooldown <= 0) {
        this.contactCooldown = 2.2;
        game.reportContact(this.team, this.lastSeen, this);
      }
    } else {
      this.targetVisible = false;
      if (this.lastSeenTimer > 0) this.lastSeenTimer -= 0.2;
      if (this.target && (!this.target.alive || this.lastSeenTimer <= 0)) this.target = null;
    }
  }

  updateBehaviour(dt, game) {
    if (this.target && this.targetVisible) {
      // Retreat is a genuine tactical decision, not a scripted state.
      if (this.health < this.maxHealth * 0.28 && this.state !== 'retreat' && Math.random() < 0.008) {
        this.state = 'retreat';
        this.stateTimer = 0;
        this.path = [];
        this.goal = this.findRetreatPoint(game);
        this.goalType = 'retreat';
      } else if (this.state !== 'retreat') {
        this.state = 'engage';
      }
    } else if (this.state === 'engage') {
      this.state = 'investigate';
      this.stateTimer = 0;
      this.path = [];
      this.goal = this.lastSeen.clone();
      this.goalType = 'investigate';
    }

    if (this.state === 'engage') this.engage(dt, game);
    else if (this.state === 'retreat') this.retreat(dt, game);
    else if (this.state === 'investigate') this.investigate(dt, game);
    else if (this.state === 'regroup') this.regroup(dt, game);
    else this.patrol(dt, game);
  }

  moveTowards(game, dir, speed, dt) {
    if (dir.lengthSq() < 0.0001) { this.vel.multiplyScalar(Math.pow(0.01, dt)); return; }
    dir.normalize();
    this.vel.x = damp(this.vel.x, dir.x * speed, 9, dt);
    this.vel.z = damp(this.vel.z, dir.z * speed, 9, dt);
    const before = TMP_A.copy(this.pos);
    moveHorizontal(game.world, this.pos, this.vel.x * dt, this.vel.z * dt, 1.68, 0.38, 0.48);
    // Vertical support / gravity. Bots follow stairs via the nav links.
    const support = supportHeight(game.world, this.pos.x, this.pos.z, this.pos.y, 0.38, 0.5);
    if (support > this.pos.y) this.pos.y = support;
    else if (support < this.pos.y - 0.35) {
      this.pos.y -= Math.min(9, dt * 16);
      if (this.pos.y < support) this.pos.y = support;
    } else this.pos.y = support;

    if (!this.stateEngagingFacing) this.yaw = this.faceYaw(this.yaw, Math.atan2(dir.x, dir.z), this.skill.turnSpeed * 0.75, dt);

    const moved = Math.hypot(this.pos.x - before.x, this.pos.z - before.z);
    if (moved < 0.006) {
      this.stuckTimer += dt;
      if (this.stuckTimer > 0.55) {
        this.stuckCount++;
        this.stuckTimer = 0;
        this.path = [];
        if (this.stuckCount >= 3) {
          this.stuckCount = 0;
          const node = game.nav.nearest(this.pos);
          if (node) {
            // Safe recovery to the nearest valid nav node (never through geometry).
            this.pos.set(node.x, node.y, node.z);
            this.vel.set(0, 0, 0);
          }
        }
      }
    } else {
      this.stuckCount = Math.max(0, this.stuckCount - 0.04);
      this.stuckTimer = 0;
    }
  }

  faceYaw(current, desired, turnSpeed, dt) {
    return current + clamp(angleDiff(current, desired), -turnSpeed * dt, turnSpeed * dt);
  }

  facePitch(current, desired, turnSpeed, dt) {
    return current + clamp(desired - current, -turnSpeed * dt, turnSpeed * dt);
  }

  followPath(game, goal, speed, dt, faceMovement = true) {
    this.stateEngagingFacing = !faceMovement;
    if (!goal) { this.vel.multiplyScalar(0.8); return false; }
    this.repathTimer -= dt;
    if (!this.path.length || this.repathTimer <= 0) {
      this.repathTimer = 1.4 + Math.random() * 0.8;
      this.path = game.nav.findPath(this.pos, goal);
      this.pathIndex = 0;
      if (!this.path.length) {
        // No route: head directly toward the goal while respecting collision.
        this.path = [game.nav.nearest(goal) || goal];
        this.pathIndex = 0;
      }
    }
    let wp = this.path[this.pathIndex];
    if (!wp) return false;
    const dx = wp.x - this.pos.x, dz = wp.z - this.pos.z;
    const d = Math.hypot(dx, dz);
    if (d < 0.72) {
      this.pathIndex++;
      wp = this.path[this.pathIndex];
      if (!wp) return Math.hypot(goal.x - this.pos.x, goal.z - this.pos.z) < 1.4;
    } else {
      this.moveTowards(game, TMP_B.set(dx, 0, dz), speed, dt);
    }
    return Math.hypot(goal.x - this.pos.x, goal.z - this.pos.z) < 1.4;
  }

  patrol(dt, game) {
    this.stateEngagingFacing = false;
    this.idleTimer -= dt;
    if (!this.goal || this.state !== 'patrol' || (this.path.length && this.pathIndex >= this.path.length)) {
      if (this.idleTimer > 0) {
        this.vel.multiplyScalar(Math.pow(0.01, dt));
        return;
      }
      this.state = 'patrol';
      const target = this.pickPatrolPoint(game);
      this.goal = target;
      this.goalType = 'patrol';
      this.path = [];
      this.idleTimer = 1.3 + Math.random() * 3.5;
    }
    const arrived = this.followPath(game, this.goal, 3.15, dt);
    if (arrived) {
      this.goal = null;
      this.path = [];
      this.idleTimer = 1.2 + Math.random() * 2.6;
      // Sometimes switch to explore or regroup for more varied movement.
      if (Math.random() < 0.15) {
        this.state = 'explore';
        this.stateTimer = 0;
      }
    }
  }

  investigate(dt, game) {
    this.stateEngagingFacing = false;
    if (this.lastSeenTimer <= 0 && this.stateTimer > 2.0) {
      this.state = 'patrol';
      this.goal = null;
      this.path = [];
      this.idleTimer = 0.4;
      return;
    }
    if (!this.goal) this.goal = this.lastSeen.clone();
    if (this.state === 'explore') {
      this.lastSeenTimer = Math.max(this.lastSeenTimer, 0.2);
    }
    const arrived = this.followPath(game, this.goal, 3.8, dt);
    if (arrived) {
      this.stateTimer = 0;
      this.state = 'investigate';
      // Look around while searching.
      this.yaw += dt * 1.2;
      this.vel.multiplyScalar(Math.pow(0.01, dt));
      if (this.stateTimer > 2.4 || this.lastSeenTimer <= 0) {
        this.state = 'patrol';
        this.goal = null;
        this.path = [];
        this.idleTimer = 0.8;
      }
    }
  }

  retreat(dt, game) {
    this.stateEngagingFacing = false;
    if (!this.goal) this.goal = this.findRetreatPoint(game);
    const arrived = this.followPath(game, this.goal, 4.0, dt);
    // Fire back while retreating, less accurately.
    if (this.target && this.targetVisible) this.tryFire(game, 1.35);
    if (arrived || this.stateTimer > 3.2 || this.health > this.maxHealth * 0.45) {
      this.state = 'patrol';
      this.stateTimer = 0;
      this.goal = null;
      this.path = [];
      this.idleTimer = 0.7;
    }
  }

  regroup(dt, game) {
    this.stateEngagingFacing = false;
    if (!this.goal || this.stateTimer > 4) {
      const teammates = game.bots.filter(b => b !== this && b.alive && b.team === this.team);
      if (!teammates.length) { this.state = 'patrol'; this.goal = null; return; }
      const mate = teammates[Math.floor(Math.random() * teammates.length)];
      this.goal = new THREE.Vector3(mate.pos.x, mate.pos.y, mate.pos.z);
      this.stateTimer = 0;
      this.path = [];
    }
    this.followPath(game, this.goal, 3.7, dt);
    if (this.goal && Math.hypot(this.goal.x - this.pos.x, this.goal.z - this.pos.z) < 2.2) {
      this.state = 'patrol';
      this.goal = null;
      this.path = [];
    }
  }

  pickPatrolPoint(game) {
    const nodes = game.nav.nodes;
    if (!nodes.length) return this.pos.clone();
    let best = null;
    for (let i = 0; i < 8; i++) {
      const n = nodes[Math.floor(Math.random() * nodes.length)];
      const d = Math.hypot(n.x - this.pos.x, n.z - this.pos.z);
      if (d > 8 && d < 44) { best = n; break; }
    }
    best ||= nodes[Math.floor(Math.random() * nodes.length)];
    return new THREE.Vector3(best.x, best.y, best.z);
  }

  findRetreatPoint(game) {
    const nodes = game.nav.nodes;
    const threat = this.target ? (this.target.isPlayer ? this.target.pos : this.target.pos) : null;
    let best = null, bestScore = -Infinity;
    for (let i = 0; i < Math.min(nodes.length, 40); i++) {
      const n = nodes[Math.floor(Math.random() * nodes.length)];
      let score = Math.hypot(n.x - this.pos.x, n.z - this.pos.z);
      if (threat) score += Math.hypot(n.x - threat.x, n.z - threat.z) * 0.9;
      if (score > bestScore) { bestScore = score; best = n; }
    }
    return best ? new THREE.Vector3(best.x, best.y, best.z) : this.pos.clone();
  }

  engage(dt, game) {
    const target = this.target;
    if (!target || !target.alive) { this.state = 'patrol'; this.goal = null; return; }
    const eye = this.getEyeWorld();
    const targetEye = target.isPlayer ? target.eyePosition() : target.getEyeWorld();
    const targetChest = new THREE.Vector3(target.pos.x, target.pos.y + (target.isPlayer ? 1.2 : 1.25), target.pos.z);
    const dx = targetChest.x - eye.x, dz = targetChest.z - eye.z;
    const dist = Math.hypot(dx, dz);
    const desiredYaw = Math.atan2(dx, dz);
    const vertical = targetChest.y - eye.y;
    const desiredPitch = Math.atan2(vertical, Math.max(0.2, dist));

    this.yaw = this.faceYaw(this.yaw, desiredYaw, this.skill.turnSpeed, dt);
    this.pitch = this.facePitch(this.pitch, desiredPitch, this.skill.turnSpeed, dt);
    this.stateEngagingFacing = true;

    // Tactical movement: advance, hold, retreat or strafe.
    const preferred = 8.5 + (this.skillName === 'Easy' ? 6 : this.skillName === 'Hard' ? 1 : 3);
    const dir = TMP_A.set(dx, 0, dz).normalize();
    if (!this.targetVisible) {
      // Chase the last known position.
      this.followPath(game, this.lastSeen.clone(), 4.2, dt);
    } else if (dist > preferred + 4.5) {
      this.followPath(game, targetChest, 3.9, dt);
    } else if (dist < 4.0) {
      this.moveTowards(game, TMP_B.set(-dir.x, 0, -dir.z), 2.8, dt);
    } else {
      const strafe = TMP_B.set(-dir.z * this.strafeDir, 0, dir.x * this.strafeDir);
      strafe.multiplyScalar(this.skill.strafe * 2.4);
      this.moveTowards(game, strafe, 1.1 + this.skill.strafe, dt);
    }

    if (this.targetVisible) this.tryFire(game);
  }

  tryFire(game, inaccuracyMult = 1) {
    if (this.reloadT > 0) return;
    if (this.ammo <= 0) { this.reloadT = 2.1 + Math.random() * 0.5; return; }
    if (this.fireCooldown > 0) return;
    if (this.reactionTimer > 0) return;
    if (!this.target || !this.targetVisible) return;

    const target = this.target;
    const eye = this.getEyeWorld();
    const boxes = target.getHitboxes();
    const headChance = this.skillName === 'Hard' ? 0.22 : this.skillName === 'Normal' ? 0.11 : 0.04;
    const box = Math.random() < headChance ? boxes[0] : boxes[Math.min(boxes.length - 1, 1)];
    const aim = new THREE.Vector3(box.x, box.y, box.z);

    // Aim error scales with distance, movement and difficulty.
    const moving = Math.hypot(this.vel.x, this.vel.z);
    const error = this.skill.aimError * inaccuracyMult * (1 + moving * 0.12) * (1 + Math.hypot(aim.x - eye.x, aim.z - eye.z) * 0.012);
    aim.x += (Math.random() - 0.5) * error * 8;
    aim.y += (Math.random() - 0.5) * error * 6;
    aim.z += (Math.random() - 0.5) * error * 8;

    const dir = aim.sub(eye).normalize();
    // Verify muzzle line has not been blocked between perception and trigger.
    if (rayBlocked(game.world, eye, new THREE.Vector3(box.x, box.y, box.z), 0.1)) return;

    const muzzle = this.soldier.getMuzzleWorld();
    game.effects?.muzzle(muzzle, 0xffbd6b, 0.8);
    game.audio?.shot('rifle', this.pos.distanceTo(game.player.pos));
    game.botShoot(this, eye, dir);

    this.ammo--;
    this.fireCooldown = this.skill.fireDelay[0] + Math.random() * (this.skill.fireDelay[1] - this.skill.fireDelay[0]);
    if (this.skillName === 'Hard') this.fireCooldown *= 0.82;
    this.burstLeft++;
    if (this.burstLeft > this.skill.burst[1] || Math.random() < 0.12) {
      this.burstLeft = 0;
      this.fireCooldown += 0.25 + Math.random() * 0.55;
    }
    this.soldier.kick();
    if (this.ammo <= 0) this.reloadT = 2.2;
  }
}

// Match rules, scoring, hit-scan combat and respawn management.
import * as THREE from 'three';
import { PLAYER, MODES, DIFFICULTIES, BOT_NAMES, clamp } from './config.js';
import { raycastWorld, raySphere, rayBlocked, isSpawnFree } from './physics.js';
import { Bot } from './bots.js';

export class Game {
  constructor({ scene, player, world, effects, audio, materials, ui = null }) {
    this.scene = scene;
    this.player = player;
    this.world = world;
    this.effects = effects;
    this.audio = audio;
    this.materials = materials;
    this.ui = ui;
    this.bots = [];
    this.mode = MODES.tdm;
    this.mapBuilder = null;
    this.teamScores = { CT: 0, T: 0 };
    this.timeRemaining = 300;
    this.scoreLimit = 50;
    this.timeLimit = 300;
    this.state = 'idle'; // idle | playing | ended
    this.paused = false;
    this.difficulty = 'Normal';
    this.playerTeam = 'CT';
    this.config = null;
    this.listeners = new Map();
    this.lastKill = null;
    this.deathNoticeTimer = 0;
    this.matchStartedAt = 0;
    this.frameDamage = 0;
  }

  on(event, fn) {
    if (!this.listeners.has(event)) this.listeners.set(event, new Set());
    this.listeners.get(event).add(fn);
    return () => this.listeners.get(event)?.delete(fn);
  }

  emit(event, payload) {
    for (const fn of this.listeners.get(event) || []) {
      try { fn(payload); } catch (err) { console.error(err); }
    }
  }

  start(config, mapBuilder) {
    this.config = { ...config };
    this.mode = MODES[config.modeId] || MODES.tdm;
    this.mapBuilder = mapBuilder;
    this.world = mapBuilder;
    this.playerTeam = this.mode.teamBased ? config.team : 'FFA';
    this.player.team = this.playerTeam;
    this.difficulty = DIFFICULTIES[config.difficulty] ? config.difficulty : 'Normal';
    this.scoreLimit = config.scoreLimit;
    this.timeLimit = config.timeLimit;
    this.timeRemaining = this.timeLimit;
    this.teamScores = { CT: 0, T: 0 };
    this.state = 'playing';
    this.paused = false;
    this.matchStartedAt = performance.now();
    this.deathNoticeTimer = 0;

    // Clear previous combatants.
    for (const b of this.bots) b.soldier.group.removeFromParent();
    this.bots = [];

    // Player stats.
    this.player.score = 0;
    this.player.kills = 0;
    this.player.deaths = 0;
    this.player.streak = 0;
    this.player.spawnProtection = 1.2;

    const spawn = this.pickSpawn(this.playerTeam, this.player);
    this.player.reset(spawn, this.yawForSpawn(spawn, this.playerTeam));
    this.effects?.reset();

    // Roster: balanced teams for TDM, every bot independent in FFA.
    const count = Math.max(1, Math.min(15, config.botCount | 0));
    const names = [...BOT_NAMES].sort(() => Math.random() - 0.5);
    for (let i = 0; i < count; i++) {
      let team;
      if (this.mode.teamBased) {
        const mates = Math.floor(count / 2);
        team = i < mates ? this.playerTeam : (this.playerTeam === 'CT' ? 'T' : 'CT');
      } else {
        team = i % 2 === 0 ? 'CT' : 'T';
      }
      const bot = new Bot({
        team,
        name: names[i % names.length] + (i >= names.length ? `-${i}` : ''),
        materials: this.materials,
        scene: this.scene,
        difficulty: this.difficulty,
        index: i,
      });
      bot.score = 0; bot.kills = 0; bot.deaths = 0; bot.spawnProtection = 1.2;
      const bspawn = this.pickSpawn(team, bot);
      bot.reset(bspawn, this.yawForSpawn(bspawn, team));
      this.bots.push(bot);
    }

    this.emit('start', this.snapshot());
    this.audio?.setMatchActive?.(true);
    return this;
  }

  yawForSpawn(spawn, team) {
    if (this.mapBuilder?.spawnYaw && this.mode.teamBased && this.mapBuilder.spawnYaw[team] !== undefined) {
      return this.mapBuilder.spawnYaw[team];
    }
    // Face roughly toward the middle of the map.
    return Math.atan2(-spawn.x, -spawn.z);
  }

  pickSpawn(team, self = null) {
    const builder = this.mapBuilder;
    let pool = [];
    if (builder.spawns[team]?.length) pool = builder.spawns[team];
    else pool = [...(builder.spawns.CT || []), ...(builder.spawns.T || [])];
    if (!pool.length) return new THREE.Vector3(0, 0, 0);
    const enemies = this.combatants().filter(e => e !== self && e.alive && (this.mode.teamBased ? e.team !== team : true));
    let best = null, bestScore = -Infinity;
    for (let attempt = 0; attempt < Math.min(pool.length, 8); attempt++) {
      const p = pool[Math.floor(Math.random() * pool.length)];
      let score = 100;
      for (const e of enemies) score += Math.min(50, Math.hypot(e.pos.x - p.x, e.pos.z - p.z));
      score += Math.random() * 25;
      if (score > bestScore) { bestScore = score; best = p; }
    }
    const spawn = best ? best.clone() : pool[0].clone();
    spawn.x += (Math.random() - 0.5) * 1.4;
    spawn.z += (Math.random() - 0.5) * 1.4;
    if (!isSpawnFree(this.world, spawn.x, spawn.z, 0.4)) {
      const safe = pool.find(p => isSpawnFree(this.world, p.x, p.z, 0.4));
      if (safe) spawn.copy(safe);
    }
    return spawn;
  }

  combatants() {
    return [this.player, ...this.bots];
  }

  isEnemy(a, b) {
    if (a === b) return false;
    if (!this.mode.teamBased) return true;
    return a.team !== b.team;
  }

  spawnEntity(entity) {
    const team = entity === this.player ? this.playerTeam : entity.team;
    const spawn = this.pickSpawn(team, entity);
    if (entity === this.player) {
      this.player.reset(spawn, this.yawForSpawn(spawn, team));
      this.player.spawnProtection = 1.4;
      this.emit('playerRespawn', { spawn });
    } else {
      entity.reset(spawn, this.yawForSpawn(spawn, team));
      entity.spawnProtection = 1.4;
    }
  }

  update(dt, input) {
    if (this.state !== 'playing' || this.paused) return;
    this.timeRemaining = Math.max(0, this.timeRemaining - dt);
    if (this.timeRemaining <= 0) { this.endMatch('TIME LIMIT'); return; }

    if (this.player.spawnProtection > 0) this.player.spawnProtection -= dt;
    this.player.update(dt, { world: this.world, input, game: this });

    for (const bot of this.bots) {
      if (bot.spawnProtection > 0) bot.spawnProtection -= dt;
      bot.update(dt, this);
    }

    // Respawn timers.
    if (!this.player.alive && this.player.respawnTimer <= 0) {
      this.spawnEntity(this.player);
      this.emit('respawned', { player: true });
    }
    for (const bot of this.bots) {
      if (!bot.alive && bot.respawnTimer <= 0) this.spawnEntity(bot);
    }

    this.separateBots(dt);
    this.frameDamage = Math.max(0, this.frameDamage - dt);
    if (this.frameDamage === 0) this.emit('damageClear');
  }

  separateBots(dt) {
    // Cheap local separation so bots do not stack into each other.
    const all = [this.player, ...this.bots];
    for (let i = 1; i < all.length; i++) {
      const a = all[i];
      if (!a.alive) continue;
      for (let j = 0; j < i; j++) {
        const b = all[j];
        if (!b.alive) continue;
        const dx = a.pos.x - b.pos.x, dz = a.pos.z - b.pos.z;
        const d2 = dx * dx + dz * dz;
        const min = 0.72;
        if (d2 < min * min && d2 > 0.0001) {
          const d = Math.sqrt(d2);
          const push = (min - d) * 0.5;
          const nx = dx / d, nz = dz / d;
          if (a !== this.player && isSpawnFree(this.world, a.pos.x + nx * push, a.pos.z + nz * push, 0.3)) {
            a.pos.x += nx * push; a.pos.z += nz * push;
          }
          if (b !== this.player && isSpawnFree(this.world, b.pos.x - nx * push, b.pos.z - nz * push, 0.3)) {
            b.pos.x -= nx * push; b.pos.z -= nz * push;
          }
        }
      }
    }
  }

  // Nearest wall or combatant along a bullet ray.
  raycastShot(origin, dir, range, shooter) {
    let wall = raycastWorld(this.world, origin, dir, range);
    let best = null;
    let bestDist = wall ? wall.distance : range;
    for (const entity of this.combatants()) {
      if (!entity.alive || entity === shooter) continue;
      if (shooter === 'player') {
        // The player can hit anyone hostile.
        if (this.mode.teamBased && entity.team === this.playerTeam) continue;
      } else if (!this.isEnemy(shooter, entity)) continue;
      for (const box of entity.getHitboxes()) {
        const hit = raySphere(origin.x, origin.y, origin.z, dir.x, dir.y, dir.z, box.x, box.y, box.z, box.radius);
        if (hit && hit.distance < bestDist) {
          bestDist = hit.distance;
          best = {
            entity, part: box.part, mult: box.mult, point: hit.point,
            normal: dir.clone().negate(), bot: entity.isPlayer ? null : entity,
            player: !!entity.isPlayer, material: 'dirt', headshot: box.part === 'head',
          };
        }
      }
    }
    if (best) return best;
    if (wall) {
      return {
        point: new THREE.Vector3(origin.x + dir.x * wall.distance, origin.y + dir.y * wall.distance, origin.z + dir.z * wall.distance),
        normal: wall.normal,
        material: wall.collider.material || 'concrete',
        distance: wall.distance,
      };
    }
    return null;
  }

  botShoot(bot, origin, dir) {
    const result = this.raycastShot(origin, dir, 90, bot);
    const muzzle = bot.soldier.getMuzzleWorld();
    if (result?.point) {
      this.effects?.tracer(muzzle, result.point);
      this.effects?.impact(result.point, result.normal || dir.clone().negate(), result.material || 'concrete', 0.8);
    }
    if (!result) return;
    const headshot = result.headshot;
    const dmg = (bot.skill?.damage || 11) * (result.mult || 1);
    if (result.player) {
      this.damagePlayer(dmg, bot, { headshot, weapon: 'CV-47', direction: dir });
    } else if (result.entity && !result.entity.isPlayer) {
      this.damageBot(result.entity, dmg, bot, headshot, 'CV-47');
    }
  }

  damageBot(bot, amount, attacker, headshot, weaponName = 'CV-47') {
    if (!bot || !bot.alive || this.state !== 'playing') return;
    if (bot.spawnProtection > 0) return;
    bot.health -= amount;
    this.emit('botDamaged', { bot, amount, attacker, headshot });
    if (bot.health > 0) return;

    bot.health = 0;
    bot.die();
    bot.deaths++;
    bot.respawnTimer = PLAYER.respawnDelay;
    const killer = attacker === this.player ? this.player : attacker;
    if (killer) {
      killer.score = (killer.score || 0) + 1;
      killer.kills = (killer.kills || 0) + 1;
      if (killer === this.player) {
        this.player.streak = (this.player.streak || 0) + 1;
        this.audio?.kill();
      }
      if (this.mode.teamBased) this.teamScores[killer.team] = (this.teamScores[killer.team] || 0) + 1;
    }
    this.reportKill(killer, bot, headshot, weaponName);
    this.emit('kill', this.lastKill);
    if (this.checkScoreLimit()) return;
  }

  damagePlayer(amount, attacker, { headshot = false, weapon = 'CV-47', direction = null } = {}) {
    if (!this.player.alive || this.state !== 'playing') return;
    if (this.player.spawnProtection > 0) return;
    const res = this.player.takeDamage(amount, attacker, { headshot, weapon });
    this.frameDamage = 0.35;
    this.audio?.hurt();
    const dir = direction ? direction.clone().negate() : null;
    this.emit('playerDamaged', { amount, health: this.player.health, armor: this.player.armor, direction: dir, headshot });
    if (!res?.killed) return;

    this.player.deaths++;
    this.player.streak = 0;
    if (attacker && attacker !== this.player) {
      attacker.score = (attacker.score || 0) + 1;
      attacker.kills = (attacker.kills || 0) + 1;
      if (this.mode.teamBased) this.teamScores[attacker.team] = (this.teamScores[attacker.team] || 0) + 1;
    }
    this.reportKill(attacker, this.player, headshot, weapon);
    this.emit('kill', this.lastKill);
    this.emit('playerKilled', { attacker, headshot });
    this.checkScoreLimit();
  }

  reportKill(killer, victim, headshot, weapon) {
    this.lastKill = {
      killer: killer ? (killer === this.player ? this.playerName() : killer.name) : 'WORLD',
      victim: victim === this.player ? this.playerName() : victim.name,
      killerTeam: killer?.team || null,
      victimTeam: victim.team || null,
      headshot: !!headshot,
      weapon,
      playerKill: killer === this.player,
      playerDeath: victim === this.player,
    };
  }

  playerName() { return this.player.displayName || 'Operator'; }

  checkScoreLimit() {
    if (this.mode.teamBased) {
      if (this.teamScores.CT >= this.scoreLimit) { this.endMatch('SCORE LIMIT', 'CT'); return true; }
      if (this.teamScores.T >= this.scoreLimit) { this.endMatch('SCORE LIMIT', 'T'); return true; }
    } else {
      for (const c of this.combatants()) {
        if ((c.score || 0) >= this.scoreLimit) { this.endMatch('SCORE LIMIT'); return true; }
      }
    }
    return false;
  }

  reportContact(team, pos, source) {
    if (Math.random() < 0.15) return;
    for (const bot of this.bots) {
      if (bot === source || !bot.alive || bot.team !== team) continue;
      if (bot.pos.distanceTo(pos) < 38) bot.reportContact(pos);
    }
  }

  snapshot() {
    return {
      mode: this.mode,
      map: this.config?.mapId,
      teamScores: { ...this.teamScores },
      timeRemaining: this.timeRemaining,
      scoreLimit: this.scoreLimit,
      playerTeam: this.playerTeam,
      state: this.state,
    };
  }

  scoreboard() {
    const rows = this.combatants().map(c => ({
      name: c === this.player ? this.playerName() : c.name,
      team: c === this.player ? this.playerTeam : c.team,
      score: c.score || 0,
      kills: c.kills || 0,
      deaths: c.deaths || 0,
      isPlayer: c === this.player,
      alive: c.alive,
      bot: c !== this.player,
      state: c === this.player ? 'PLAYER' : c.state?.toUpperCase() || 'BOT',
    }));
    rows.sort((a, b) => b.score - a.score || b.kills - a.kills);
    return rows;
  }

  endMatch(reason = 'TIME LIMIT', forcedWinner = null) {
    if (this.state === 'ended') return;
    this.state = 'ended';
    this.audio?.setMatchActive?.(false);
    let winnerTeam = forcedWinner;
    let winnerName = null;
    let draw = false;
    let playerWon = false;

    if (this.mode.teamBased) {
      if (!winnerTeam) {
        if (this.teamScores.CT > this.teamScores.T) winnerTeam = 'CT';
        else if (this.teamScores.T > this.teamScores.CT) winnerTeam = 'T';
        else draw = true;
      }
      playerWon = !draw && winnerTeam === this.playerTeam;
      const label = winnerTeam === 'CT' ? 'COUNTER-TERRORISTS' : 'TERRORISTS';
      winnerName = draw ? 'DRAW' : label;
    } else {
      const sorted = this.combatants().slice().sort((a, b) => (b.score || 0) - (a.score || 0));
      const top = sorted[0], second = sorted[1];
      if (top && second && (top.score || 0) === (second.score || 0)) draw = true;
      winnerName = draw ? 'DRAW' : (top === this.player ? this.playerName() : top?.name || 'NO WINNER');
      playerWon = !draw && top === this.player;
    }

    const duration = Math.max(0, (performance.now() - this.matchStartedAt) / 1000);
    const result = {
      winnerName, winnerTeam, draw, playerWon, reason, duration,
      mode: this.mode,
      mapId: this.config?.mapId,
      teamScores: { ...this.teamScores },
      playerTeam: this.playerTeam,
      rows: this.scoreboard(),
      playerScore: this.player.score || 0,
      playerKills: this.player.kills || 0,
      playerDeaths: this.player.deaths || 0,
      scoreLimit: this.scoreLimit,
    };
    this.lastResult = result;
    this.audio?.matchEnd(playerWon);
    this.emit('end', result);
  }

  stop() {
    this.state = 'idle';
    this.paused = false;
    for (const b of this.bots) b.soldier.group.removeFromParent();
    this.bots = [];
    this.effects?.reset();
    this.audio?.setMatchActive?.(false);
  }
}

@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800&family=IBM+Plex+Mono:wght@400;500;600&display=swap');

:root {
  --bg: #10110e;
  --ink: #e9e5d8;
  --muted: #9b978a;
  --dim: #6f6d62;
  --amber: #d8ad68;
  --amber-hot: #f0ce91;
  --line: rgba(226, 214, 184, 0.18);
  --line-strong: rgba(226, 214, 184, 0.34);
  --panel: rgba(16, 17, 14, 0.93);
  --ct: #86a9ba;
  --t: #c08a5a;
  --green: #9caf89;
  font-family: 'IBM Plex Mono', ui-monospace, monospace;
  color: var(--ink);
  background: var(--bg);
  font-synthesis: none;
}

* { box-sizing: border-box; }
html, body, #app { margin: 0; width: 100%; height: 100%; overflow: hidden; }
body { background: #0c0d0a; }
button, input, select { font: inherit; }
button { cursor: pointer; }
.hidden { display: none !important; }

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  filter: saturate(0.82) contrast(1.055) brightness(0.98);
}
#grade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    radial-gradient(ellipse at center, transparent 42%, rgba(6, 8, 5, 0.36) 100%),
    linear-gradient(180deg, rgba(20, 18, 12, 0.14), transparent 25%, transparent 72%, rgba(6, 7, 5, 0.36));
  mix-blend-mode: multiply;
}
#grain {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 2;
  opacity: 0.10;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.34'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
}

/* ── Screens ─────────────────────────────────────────────────────────── */
.screen { position: absolute; inset: 0; z-index: 5; }
.screen.visible { display: block; }
.menu-shade {
  position: absolute; inset: 0;
  background:
    linear-gradient(90deg, rgba(7, 9, 6, 0.96) 0%, rgba(8, 10, 7, 0.89) 36%, rgba(8, 9, 7, 0.5) 68%, rgba(7, 8, 6, 0.34) 100%),
    linear-gradient(0deg, rgba(8, 9, 6, 0.94) 0%, transparent 28%, rgba(7, 8, 6, 0.18) 100%);
  backdrop-filter: blur(1.2px);
}

.brand { position: absolute; top: 5.8%; left: 6.2%; display: flex; align-items: center; gap: 15px; z-index: 2; }
.brand-mark {
  width: 50px; height: 54px; display: grid; place-items: center;
  background: linear-gradient(145deg, #dcb47a, #896238);
  clip-path: polygon(0 0, 100% 0, 100% 73%, 50% 100%, 0 73%);
  font: 800 36px 'Barlow Condensed', sans-serif; color: #171610;
  text-shadow: 0 1px rgba(255, 255, 255, 0.28);
}
.brand h1 { margin: 0; font: 800 31px 'Barlow Condensed', sans-serif; letter-spacing: 3.2px; color: #f2ede1; line-height: 1; }
.brand h1 span { color: var(--amber); }
.brand p { margin: 4px 0 0; font-size: 8.5px; letter-spacing: 2.8px; color: #8f8b7c; }
.build-chip {
  display: flex; align-items: center; gap: 7px; margin-left: 20px;
  padding: 5px 9px; border: 1px solid rgba(216, 173, 104, 0.28);
  font-size: 8px; letter-spacing: 1.3px; color: #bcb39c; background: rgba(20, 21, 17, 0.62);
}
.build-chip i { width: 6px; height: 6px; border-radius: 50%; background: #8ca474; box-shadow: 0 0 7px #8ca474; }

.menu-body {
  position: absolute; left: 6.2%; right: 6.2%; top: 19.5%; bottom: 10.5%;
  display: grid; grid-template-columns: minmax(300px, 350px) minmax(420px, 640px);
  gap: clamp(28px, 5.2vw, 92px); align-items: center; z-index: 2;
}

.main-menu { display: flex; flex-direction: column; gap: 4px; max-width: 360px; }
.main-menu button {
  display: grid; grid-template-columns: 34px 1fr 18px; align-items: center; gap: 10px;
  width: 100%; text-align: left; color: #ddd8c9;
  background: linear-gradient(90deg, rgba(109, 98, 74, 0.15), rgba(25, 27, 22, 0.2));
  border: 1px solid rgba(185, 167, 122, 0.16); border-left: 2px solid rgba(163, 143, 98, 0.4);
  padding: 9px 12px 9px 10px; transition: 140ms ease;
  position: relative; overflow: hidden;
}
.main-menu button::after {
  content: ''; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(213, 171, 100, 0.14), transparent 75%);
  opacity: 0; transition: 140ms;
}
.main-menu button:hover, .main-menu button:focus-visible {
  outline: none; color: #fff6e4; border-color: rgba(216, 173, 104, 0.62);
  border-left-color: var(--amber); transform: translateX(4px);
  background: linear-gradient(90deg, rgba(167, 128, 69, 0.3), rgba(44, 41, 30, 0.35));
}
.main-menu button:hover::after, .main-menu button:focus-visible::after { opacity: 1; }
.main-menu button.primary { background: linear-gradient(90deg, rgba(177, 133, 68, 0.28), rgba(49, 43, 30, 0.3)); border-left-color: var(--amber); }
.main-menu .idx { font-size: 8px; letter-spacing: 0.5px; color: #7f7a6b; padding-left: 2px; }
.main-menu button:hover .idx { color: var(--amber); }
.main-menu b { display: block; font: 600 17px 'Barlow Condensed', sans-serif; letter-spacing: 1.35px; }
.main-menu small { display: block; font-size: 8.5px; letter-spacing: 0.15px; color: #8d897c; margin-top: 2px; }
.main-menu em { font-style: normal; font-size: 16px; color: #817b6a; }
.main-menu button:hover em { color: var(--amber-hot); }

/* Briefing card */
.briefing { align-self: center; border: 1px solid rgba(222, 205, 165, 0.22); background: linear-gradient(140deg, rgba(31, 32, 26, 0.9), rgba(13, 15, 12, 0.88)); padding: 20px 22px 16px; box-shadow: 0 24px 70px rgba(0, 0, 0, 0.45); }
.briefing-kicker { font-size: 8px; letter-spacing: 1.8px; color: #b99358; }
.briefing h2 { margin: 8px 0 7px; font: 700 38px/0.94 'Barlow Condensed', sans-serif; letter-spacing: 0.4px; color: #eee9dc; }
.briefing h2 span { color: #a89e82; }
.briefing > p { margin: 0 0 15px; max-width: 470px; font-size: 10px; line-height: 1.65; color: #aaa596; }
.map-preview { position: relative; height: 166px; overflow: hidden; border: 1px solid rgba(196, 172, 121, 0.28); background: radial-gradient(circle at 48% 46%, #857557 0%, #5e5542 46%, #3f3c30 100%); }
.map-grid { position: absolute; inset: 0; background-image: linear-gradient(rgba(235, 218, 177, 0.08) 1px, transparent 1px), linear-gradient(90deg, rgba(235, 218, 177, 0.08) 1px, transparent 1px); background-size: 28px 28px; }
.map-blocks i { position: absolute; background: linear-gradient(145deg, #a99772, #7c6b4e); box-shadow: inset 0 0 0 1px rgba(47, 38, 23, 0.35), 2px 3px 0 rgba(36, 30, 20, 0.45); }
.map-blocks .b1 { left: 8%; top: 11%; width: 22%; height: 24%; }
.map-blocks .b2 { right: 8%; top: 11%; width: 22%; height: 24%; }
.map-blocks .b3 { left: 8%; bottom: 11%; width: 22%; height: 24%; }
.map-blocks .b4 { right: 8%; bottom: 11%; width: 22%; height: 24%; }
.map-blocks .b5 { left: 36%; top: 5%; width: 11%; height: 18%; }
.map-blocks .b6 { right: 36%; top: 5%; width: 11%; height: 18%; }
.map-blocks .b7 { left: 36%; bottom: 5%; width: 11%; height: 18%; }
.map-blocks .b8 { right: 36%; bottom: 5%; width: 11%; height: 18%; }
.map-blocks .plaza { left: 41%; top: 38%; width: 18%; height: 24%; border-radius: 50%; background: #a5a07f; box-shadow: inset 0 0 0 3px #7d7560; }
.map-blocks .route { background: rgba(224, 207, 162, 0.16); }
.map-blocks .r1 { left: 48.5%; top: 24%; width: 3%; height: 14%; }
.map-blocks .r2 { left: 48.5%; bottom: 24%; width: 3%; height: 14%; }
.map-blocks .site { position: absolute; font: 700 12px 'IBM Plex Mono', monospace; color: #f1d397; width: 20px; height: 20px; display: grid; place-items: center; border: 1px solid rgba(238, 207, 145, 0.7); border-radius: 50%; background: rgba(42, 36, 24, 0.54); }
.map-blocks .s1 { left: 31%; top: 44%; }
.map-blocks .s2 { right: 31%; top: 44%; }
.map-blocks .compass { position: absolute; right: 9px; top: 7px; font: 9px 'IBM Plex Mono'; color: #e9d8ae; letter-spacing: 1px; }
.map-preview.industrial { background: radial-gradient(circle at 46% 46%, #66716f 0%, #454e4d 47%, #2c3332 100%); }
.map-preview.industrial .map-blocks i { background: linear-gradient(145deg, #7c8784, #4c5755); box-shadow: inset 0 0 0 1px rgba(20, 27, 26, 0.5), 2px 3px 0 rgba(18, 23, 22, 0.5); }
.map-preview.industrial .map-blocks .plaza { background: #727a72; box-shadow: inset 0 0 0 3px #525b55; }
.map-preview.industrial .map-blocks .site { color: #d4dfd5; border-color: rgba(192, 210, 200, 0.68); }
.map-caption { position: absolute; left: 10px; right: 10px; bottom: 8px; display: flex; justify-content: space-between; align-items: center; font-size: 8px; letter-spacing: 0.8px; color: #ddd1ae; text-shadow: 0 1px 2px #000; }
.map-caption b { font-weight: 500; color: #bcb194; }
.briefing-stats { display: grid; grid-template-columns: 1.15fr 1fr 0.8fr; gap: 9px; border-top: 1px solid rgba(219, 201, 160, 0.15); margin-top: 14px; padding-top: 13px; }
.briefing-stats small { display: block; font-size: 7px; letter-spacing: 1.2px; color: #777467; margin-bottom: 3px; }
.briefing-stats strong { font: 600 11px 'Barlow Condensed', sans-serif; letter-spacing: 1px; color: #d7d2c4; }
.briefing-stats strong.ready { color: #a7bd8e; }
.briefing-stats strong.ready i { display: inline-block; width: 5px; height: 5px; border-radius: 50%; background: #90ab79; margin-right: 5px; box-shadow: 0 0 6px #90ab79; }
.briefing-actions { display: flex; gap: 8px; margin-top: 13px; }
.briefing-actions button { flex: 1; padding: 9px 11px; font: 600 12px 'Barlow Condensed', sans-serif; letter-spacing: 1.3px; color: #11120e; background: linear-gradient(180deg, #e1bb7b, #b58b4f); border: 1px solid #e7c58c; }
.briefing-actions button.brief-alt { color: #d6d1c2; background: rgba(39, 39, 31, 0.6); border-color: rgba(206, 189, 148, 0.3); }
.briefing-actions button:hover { filter: brightness(1.08); }

.menu-footer { position: absolute; left: 6.2%; right: 6.2%; bottom: 3.3%; display: flex; gap: 26px; align-items: center; font-size: 7.5px; letter-spacing: 0.9px; color: #666459; z-index: 2; }
.menu-footer span:last-child { margin-left: auto; color: #777368; }
.menu-footer .menu-controls { font-size: 7px; letter-spacing: 0.5px; opacity: 0.8; }

/* ── Modal ───────────────────────────────────────────────────────────── */
.modal-root { position: absolute; inset: 0; z-index: 30; display: grid; place-items: center; }
.modal-backdrop { position: absolute; inset: 0; background: rgba(5, 6, 5, 0.72); backdrop-filter: blur(4px); }
.modal-card { position: relative; width: min(780px, 92vw); max-height: 88vh; overflow: auto; border: 1px solid rgba(191, 166, 113, 0.6); background: linear-gradient(155deg, #1d1e19 0%, #11120f 68%); box-shadow: 0 30px 120px #000b; padding: 26px 30px 24px; }
.modal-card::-webkit-scrollbar { width: 8px; }
.modal-card::-webkit-scrollbar-thumb { background: #49483b; }
.modal-head { display: flex; justify-content: space-between; gap: 20px; align-items: flex-start; margin-bottom: 17px; border-bottom: 1px solid #474637; padding-bottom: 13px; }
.modal-head h2 { margin: 0; font: 700 30px 'Barlow Condensed', sans-serif; letter-spacing: 2px; color: var(--amber-hot); }
.modal-head p { margin: 4px 0 0; font-size: 9px; letter-spacing: 1px; color: #918d7e; }
.modal-close { border: 1px solid rgba(198, 180, 141, 0.32); background: rgba(43, 42, 34, 0.6); color: #c5bfae; padding: 7px 12px; font: 600 11px 'Barlow Condensed', sans-serif; letter-spacing: 1.3px; }
.modal-close:hover { color: #fff0d2; border-color: var(--amber); }
.modal-actions { display: flex; justify-content: flex-end; gap: 9px; flex-wrap: wrap; margin-top: 21px; border-top: 1px solid #3a392e; padding-top: 16px; }
button.btn { padding: 9px 15px; color: #ded9ca; background: rgba(53, 52, 42, 0.66); border: 1px solid rgba(192, 175, 136, 0.3); font: 600 12px 'Barlow Condensed', sans-serif; letter-spacing: 1.2px; }
button.btn:hover { border-color: var(--amber); color: #fff1d4; background: rgba(103, 87, 55, 0.5); }
button.btn.primary { color: #16150f; background: linear-gradient(180deg, #e0bb7d, #b28a4f); border-color: #e6c184; }
button.btn.danger { color: #d9b3a4; border-color: rgba(160, 91, 68, 0.5); }
button.btn.danger:hover { background: rgba(112, 52, 39, 0.45); border-color: #b8644a; }

.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px 18px; }
.field { display: flex; flex-direction: column; gap: 6px; font-size: 8.5px; letter-spacing: 1px; color: #aaa596; }
.field.full { grid-column: 1 / -1; }
.field input[type="text"], .field input:not([type]), .field select, .field input[type="number"] {
  background: #24251f; color: #e7e2d4; border: 1px solid #545243; padding: 9px 10px; font: 11px 'IBM Plex Mono'; outline: none;
}
.field input:focus, .field select:focus { border-color: var(--amber); }
.field .range-row { display: flex; align-items: center; gap: 11px; }
.field input[type="range"] { flex: 1; accent-color: #c79b59; height: 4px; }
.field output { min-width: 46px; text-align: right; color: #d6bd89; font-size: 10px; }
.field .toggle-row { display: flex; align-items: center; gap: 8px; padding: 8px 0; font-size: 10px; color: #c2bdae; }
.field input[type="checkbox"] { accent-color: #b58a4e; width: 14px; height: 14px; }
.field-note { grid-column: 1 / -1; font-size: 9px; line-height: 1.7; color: #8d897a; border-left: 2px solid #63583f; padding-left: 10px; }

.segmented { display: flex; flex-wrap: wrap; gap: 5px; }
.segmented button { flex: 1; min-width: 100px; padding: 8px 9px; background: #23241e; color: #a9a496; border: 1px solid #4c4a3c; font: 600 11px 'Barlow Condensed', sans-serif; letter-spacing: 1px; }
.segmented button.active { color: #14140f; background: linear-gradient(180deg, #d9b577, #ad854b); border-color: #e1bd7f; }
.map-choice { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
