.map-choice button.active { border-color: var(--amber); background: linear-gradient(135deg, rgba(120, 99, 60, 0.42), rgba(37, 37, 29, 0.8)); }
.map-choice b { display: block; font: 600 14px 'Barlow Condensed', sans-serif; letter-spacing: 1.2px; color: #e4dfd1; }
.map-choice small { display: block; margin-top: 3px; font-size: 8px; color: #918c7e; line-height: 1.5; }
.map-choice .mini-map { height: 45px; margin-bottom: 7px; background: repeating-linear-gradient(45deg, #3b3a2f, #3b3a2f 5px, #333329 5px, #333329 10px); border: 1px solid #575144; position: relative; overflow: hidden; }
.map-choice .mini-map i { position: absolute; background: #8e8469; }
.map-choice .mini-map i:nth-child(1) { left: 9%; top: 14%; width: 26%; height: 30%; }
.map-choice .mini-map i:nth-child(2) { right: 10%; top: 15%; width: 22%; height: 27%; }
.map-choice .mini-map i:nth-child(3) { left: 12%; bottom: 12%; width: 20%; height: 28%; }
