582:     const sx = w / (b.maxX - b.minX), sz = h / (b.maxZ - b.minZ);
583:     const toX = (x) => (x - b.minX) * sx;
584:     const toZ = (z) => (z - b.minZ) * sz;
585:     ctx.clearRect(0, 0, w, h);
