606:       ctx.beginPath();
607:       ctx.fillStyle = ally ? '#79a9ba' : '#d3795d';
608:       ctx.arc(x, y, 3.1, 0, Math.PI * 2); ctx.fill();
609:       ctx.strokeStyle = 'rgba(0,0,0,.5)'; ctx.lineWidth = 1; ctx.stroke();
610:     }
