576:   updateRadar(game) {
577:     const ctx = this.radarCtx;
578:     if (!ctx || !game?.world) return;
579:     const canvas = $('#radar');
580:     const w = canvas.width, h = canvas.height;
581:     const world = game.world;
582:     const b = world.bounds;
583:     const sx = w / (b.maxX - b.minX), sz = h / (b.maxZ - b.minZ);
584:     const toX = (x) => (x - b.minX) * sx;
585:     const toZ = (z) => (z - b.minZ) * sz;
586:     ctx.clearRect(0, 0, w, h);
587:     // Map footprint.
588:     if (world.radarTexture) ctx.drawImage(world.radarTexture, 0, 0, w, h);
589:     ctx.fillStyle = 'rgba(7, 15, 12, 0.36)'; ctx.fillRect(0, 0, w, h);
590:     // Radar rings and sweep.
591:     ctx.strokeStyle = 'rgba(189, 201, 176, 0.18)'; ctx.lineWidth = 1;
592:     for (const r of [w * 0.2, w * 0.34, w * 0.48]) { ctx.beginPath(); ctx.arc(w / 2, h / 2, r, 0, Math.PI * 2); ctx.stroke(); }
593:     ctx.strokeStyle = 'rgba(189, 201, 176, 0.11)';
594:     ctx.beginPath(); ctx.moveTo(w / 2, 0); ctx.lineTo(w / 2, h); ctx.moveTo(0, h / 2); ctx.lineTo(w, h / 2); ctx.stroke();
595: 
596:     const p = game.player;
597:     const pv = p.eyePosition();
598:     for (const bot of game.bots) {
599:       if (!bot.alive) continue;
600:       const ally = game.mode.teamBased && bot.team === game.playerTeam;
601:       if (!ally) {
602:         // Only reveal enemies the player currently has line of sight to.
603:         const visible = Math.hypot(bot.pos.x - p.pos.x, bot.pos.z - p.pos.z) < 42 && !rayBlocked(world, pv, new THREE.Vector3(bot.pos.x, bot.pos.y + 1.25, bot.pos.z), 0.1);
604:         if (!visible) continue;
605:       }
606:       const x = toX(bot.pos.x), y = toZ(bot.pos.z);
607:       ctx.beginPath();
608:       ctx.fillStyle = ally ? '#79a9ba' : '#d3795d';
609:       ctx.arc(x, y, 3.1, 0, Math.PI * 2); ctx.fill();
610:       ctx.strokeStyle = 'rgba(0,0,0,.5)'; ctx.lineWidth = 1; ctx.stroke();
611:     }
612:     // Player arrow.
613:     const px = toX(p.pos.x), py = toZ(p.pos.z);
614:     ctx.save();
615:     ctx.translate(px, py);
616:     // yaw forward in world is (-sin, -cos); canvas is x/z.
617:     ctx.rotate(-p.yaw + Math.PI);
618:     ctx.fillStyle = '#f0dfa9';
619:     ctx.beginPath(); ctx.moveTo(0, -7); ctx.lineTo(4.8, 5); ctx.lineTo(0, 2.5); ctx.lineTo(-4.8, 5); ctx.closePath(); ctx.fill();
620:     ctx.strokeStyle = '#1a1a13'; ctx.lineWidth = 1; ctx.stroke();
621:     ctx.restore();
622:   }
