667:     const a = Math.abs(rel);
668:     let arc = 'front';
669:     if (a > Math.PI * 0.25 && a <= Math.PI * 0.75) arc = rel > 0 ? 'right' : 'left';
670:     else if (a > Math.PI * 0.75) arc = 'back';
671:     const el = $(`[data-arc="${arc}"]`);
672:     if (el) {
673:       el.classList.add('show');
