442:   // Static geometry is batched per material so the whole map draws in a few dozen
443:   // calls instead of hundreds. Collision and navigation data are already analytic.
444:   mergeStaticGeometry() {
445:     this.root.updateMatrixWorld(true);
446:     const rootInverse = new THREE.Matrix4().copy(this.root.matrixWorld).invert();
447:     const relative = new THREE.Matrix4();
448:     const groups = new Map();
449: 
450:     for (const child of [...this.root.children]) {
451:       if (!child.isMesh || child.isInstancedMesh || child.isSkinnedMesh) continue;
452:       if (!child.geometry || Array.isArray(child.material)) continue;
453:       if (child.material?.isShaderMaterial) continue;
454:       const key = `${child.material.uuid}|${child.castShadow ? 1 : 0}|${child.receiveShadow ? 1 : 0}`;
455:       if (!groups.has(key)) groups.set(key, []);
456:       groups.get(key).push(child);
457:     }
458: 
459:     for (const meshes of groups.values()) {
460:       if (meshes.length < 2) continue;
461:       const geometries = [];
462:       for (const mesh of meshes) {
463:         const geo = mesh.geometry.clone();
464:         relative.multiplyMatrices(rootInverse, mesh.matrixWorld);
465:         geo.applyMatrix4(relative);
466:         geometries.push(geo);
467:       }
468:       const merged = mergeGeometries(geometries, false);
469:       for (const geo of geometries) geo.dispose();
470:       if (!merged) continue;
471:       const batched = new THREE.Mesh(merged, meshes[0].material);
472:       batched.castShadow = meshes[0].castShadow;
473:       batched.receiveShadow = meshes[0].receiveShadow;
474:       for (const mesh of meshes) mesh.removeFromParent();
475:       this.root.add(batched);
476:     }
477:   }
