@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800&family=IBM+Plex+Mono:wght@400;500;600&display=swap');

:root {
  --bg: #10110e;
  --ink: #e9e5d8;
  --muted: #9b978a;
  --dim: #6f6d62;
  --amber: #d8ad68;
  --amber-hot: #f0ce91;
  --line: rgba(226, 214, 184, 0.18);
  --line-strong: rgba(226, 214, 184, 0.34);
  --panel: rgba(16, 17, 14, 0.93);
  --ct: #86a9ba;
  --t: #c08a5a;
  --green: #9caf89;
  font-family: 'IBM Plex Mono', ui-monospace, monospace;
  color: var(--ink);
  background: var(--bg);
  font-synthesis: none;
}

* { box-sizing: border-box; }
html, body, #app { margin: 0; width: 100%; height: 100%; overflow: hidden; }
body { background: #0c0d0a; }
button, input, select { font: inherit; }
button { cursor: pointer; }
.hidden { display: none !important; }

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  filter: saturate(0.82) contrast(1.055) brightness(0.98);
}
#grade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  background:
    radial-gradient(ellipse at center, transparent 42%, rgba(6, 8, 5, 0.36) 100%),
    linear-gradient(180deg, rgba(20, 18, 12, 0.14), transparent 25%, transparent 72%, rgba(6, 7, 5, 0.36));
  mix-blend-mode: multiply;
}
#grain {
  pointer-events: none;
  position: absolute;
  inset: 0;
  z-index: 2;
  opacity: 0.10;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.34'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
}

/* ── Screens ─────────────────────────────────────────────────────────── */
.screen { position: absolute; inset: 0; z-index: 5; display: none; }
.screen.visible { display: block; }
.menu-shade {
  position: absolute; inset: 0;
  background:
    linear-gradient(90deg, rgba(7, 9, 6, 0.96) 0%, rgba(8, 10, 7, 0.89) 36%, rgba(8, 9, 7, 0.5) 68%, rgba(7, 8, 6, 0.34) 100%),
    linear-gradient(0deg, rgba(8, 9, 6, 0.94) 0%, transparent 28%, rgba(7, 8, 6, 0.18) 100%);
  backdrop-filter: blur(1.2px);
}

.brand { position: absolute; top: 5.8%; left: 6.2%; display: flex; align-items: center; gap: 15px; z-index: 2; }
.brand-mark {
  width: 50px; height: 54px; display: grid; place-items: center;
  background: linear-gradient(145deg, #dcb47a, #896238);
  clip-path: polygon(0 0, 100% 0, 100% 73%, 50% 100%, 0 73%);
  font: 800 36px 'Barlow Condensed', sans-serif; color: #171610;
  text-shadow: 0 1px rgba(255, 255, 255, 0.28);
}
.brand h1 { margin: 0; font: 800 31px 'Barlow Condensed', sans-serif; letter-spacing: 3.2px; color: #f2ede1; line-height: 1; }
.brand h1 span { color: var(--amber); }
.brand p { margin: 4px 0 0; font-size: 8.5px; letter-spacing: 2.8px; color: #8f8b7c; }
.build-chip {
  display: flex; align-items: center; gap: 7px; margin-left: 20px;
  padding: 5px 9px; border: 1px solid rgba(216, 173, 104, 0.28);
  font-size: 8px; letter-spacing: 1.3px; color: #bcb39c; background: rgba(20, 21, 17, 0.62);
}
.build-chip i { width: 6px; height: 6px; border-radius: 50%; background: #8ca474; box-shadow: 0 0 7px #8ca474; }

.menu-body {
  position: absolute; left: 6.2%; right: 6.2%; top: 19.5%; bottom: 10.5%;
  display: grid; grid-template-columns: minmax(300px, 350px) minmax(420px, 640px);
  gap: clamp(28px, 5.2vw, 92px); align-items: center; z-index: 2;
}

.main-menu { display: flex; flex-direction: column; gap: 4px; max-width: 360px; }
.main-menu button {
  display: grid; grid-template-columns: 34px 1fr 18px; align-items: center; gap: 10px;
  width: 100%; text-align: left; color: #ddd8c9;
  background: linear-gradient(90deg, rgba(109, 98, 74, 0.15), rgba(25, 27, 22, 0.2));
  border: 1px solid rgba(185, 167, 122, 0.16); border-left: 2px solid rgba(163, 143, 98, 0.4);
  padding: 9px 12px 9px 10px; transition: 140ms ease;
  position: relative; overflow: hidden;
}
.main-menu button::after {
  content: ''; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(213, 171, 100, 0.14), transparent 75%);
  opacity: 0; transition: 140ms;
}
.main-menu button:hover, .main-menu button:focus-visible {
  outline: none; color: #fff6e4; border-color: rgba(216, 173, 104, 0.62);
  border-left-color: var(--amber); transform: translateX(4px);
  background: linear-gradient(90deg, rgba(167, 128, 69, 0.3), rgba(44, 41, 30, 0.35));
}
.main-menu button:hover::after, .main-menu button:focus-visible::after { opacity: 1; }
.main-menu button.primary { background: linear-gradient(90deg, rgba(177, 133, 68, 0.28), rgba(49, 43, 30, 0.3)); border-left-color: var(--amber); }
.main-menu .idx { font-size: 8px; letter-spacing: 0.5px; color: #7f7a6b; padding-left: 2px; }
.main-menu button:hover .idx { color: var(--amber); }
.main-menu b { display: block; font: 600 17px 'Barlow Condensed', sans-serif; letter-spacing: 1.35px; }
.main-menu small { display: block; font-size: 8.5px; letter-spacing: 0.15px; color: #8d897c; margin-top: 2px; }
.main-menu em { font-style: normal; font-size: 16px; color: #817b6a; }
.main-menu button:hover em { color: var(--amber-hot); }

/* Briefing card */
.briefing { align-self: center; border: 1px solid rgba(222, 205, 165, 0.22); background: linear-gradient(140deg, rgba(31, 32, 26, 0.9), rgba(13, 15, 12, 0.88)); padding: 20px 22px 16px; box-shadow: 0 24px 70px rgba(0, 0, 0, 0.45); }

