  colliders: window.__tactical?.map?.colliders?.length,
  drawCalls: window.__tactical?.renderer?.info?.render?.calls,
  triangles: window.__tactical?.renderer?.info?.render?.triangles,
  state: window.__tactical?.game?.state,
}));
console.log('MENU', JSON.stringify(menu, null, 2));
console.log('ERRORS', errors);
console.log('LOGS', logs.slice(0, 20));
await page.screenshot({ path: '/tmp/opencode/menu.png' });

// Quick play
await page.click('#main-menu button[data-action="quick"]');
await page.waitForTimeout(2000);
const playing = await page.evaluate(() => {
  const t = window.__tactical;
  return {
    state: t.game.state,
    map: t.game.config?.mapId,
    mode: t.game.config?.modeId,
    bots: t.game.bots.length,
