    hudHidden: document.querySelector('#hud').classList.contains('hidden'),
    menuVisible: document.querySelector('#menu-screen').classList.contains('visible'),
    playerPos: t.player.pos.toArray(),
    playerAlive: t.player.alive,
    nav: t.game.nav?.nodes?.length,
    drawCalls: t.renderer.info.render.calls,
  };
});
console.log('PLAYING', JSON.stringify(playing, null, 2));
await page.screenshot({ path: '/tmp/opencode/playing.png' });
console.log('ERRORS2', errors);
await browser.close();

