out.physics = await page.evaluate(() => {
  const t = window.__tactical;
  const p = t.player;
  t.game.paused = true;
  // Place in north street aiming south (+z, yaw PI).
  p.reset({ x: 0, y: 0, z: -30 }, Math.PI);
  p.spawnProtection = 0;
  const base = p.pos.z;
  const run = (input, steps = 40, dt = 1 / 60) => {
    for (let i = 0; i < steps; i++) p.update(dt, { world: t.game.world, input: { ...input }, game: t.game });
  };
  run({ forward: true });
  const afterForward = { x: p.pos.x, y: p.pos.y, z: p.pos.z };
  // walk into the north boundary wall
  p.reset({ x: 0, y: 0, z: -34.5 }, 0);
  p.spawnProtection = 0;
  run({ forward: true }, 90);
  const wallStop = { x: p.pos.x, z: p.pos.z };
  // jump
  p.reset({ x: 0, y: 0, z: 30 }, 0);
  p.spawnProtection = 0;
  run({ jumpPressed: true, forward: true }, 12);
  const jumpPeak = p.pos.y;
  run({ forward: true }, 90);
  const landedY = p.pos.y;
  const grounded = p.grounded;
  // crouch
  p.reset({ x: 0, y: 0, z: 30 }, 0);
  p.spawnProtection = 0;
  run({ crouch: true }, 45);
  const crouchEye = p.eyePosition().y;
  const standEye = (() => { p.crouching = false; p.crouchFactor = 0; return p.eyePosition().y; })();
