const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome', args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 640, height: 400 } });
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.stack));
await page.goto('http://127.0.0.1:5174/', { waitUntil: 'load' });
await page.waitForTimeout(1200);
await page.evaluate(() => {
  const t = window.__tactical;
  Object.assign(t.settings, { quality: 'low', shadows: 'off', renderScale: 0.5 });
  t.renderer.setPixelRatio(0.5); t.renderer.setSize(innerWidth, innerHeight); t.renderer.shadowMap.enabled = false;
});
const out = {};

out.spawnClearance = await page.evaluate(async () => {
  const physics = await import('/src/physics.js');
  const map = window.__tactical.map;
  const check = (arr) => arr.map(p => ({ p: [p.x, p.z], free: physics.isSpawnFree(map, p.x, p.z, 0.45) }));
  return {
    map: map.id,
    CT: check(map.spawns.CT), T: check(map.spawns.T), any: check(map.spawnsAny),
  };
});

// ── Old quarter TDM 60s simulation ──────────────────────────────────────
out.tdm = await page.evaluate(async () => {
  const t = window.__tactical;
  t.startMatch({
    mapId: 'old-quarter', modeId: 'tdm', team: 'CT', botCount: 8, difficulty: 'Normal',
    scoreLimit: 50, timeLimit: 300, playerName: 'TestOp',
  });
  const g = t.game;
  g.paused = true;
  const start = g.bots.map(b => b.pos.clone());
  let nan = false;
  let maxStep = 0;
  const prev = g.bots.map(b => b.pos.clone());
  for (let i = 0; i < 1200; i++) {
    g.paused = false;
    g.update(1 / 20, { forward: i % 120 < 60, back: false, left: i % 80 < 40, right: false, crouch: false, walk: false, jumpPressed: false, fire: true, firePressed: i % 20 === 0, aim: false, reload: false, switchWeapon: false });
    for (let j = 0; j < g.bots.length; j++) {
      const p = g.bots[j].pos;
      if (!Number.isFinite(p.x) || !Number.isFinite(p.y) || !Number.isFinite(p.z)) nan = true;
      const d = p.distanceTo(prev[j]); if (d > maxStep) maxStep = d;
      prev[j].copy(p);
    }
    if (g.state !== 'playing') break;
  }
  g.paused = true;
  const moved = g.bots.map((b, i) => start[i].distanceTo(b.pos));
  return {
    state: g.state, timeRemaining: Math.round(g.timeRemaining),
    playerTeam: g.playerTeam, teamScores: g.teamScores,
    player: { alive: t.player.alive, health: t.player.health, kills: t.player.kills, deaths: t.player.deaths, score: t.player.score, pos: t.player.pos.toArray() },
    bots: g.bots.map((b, i) => ({ name: b.name, team: b.team, state: b.state, alive: b.alive, kills: b.kills, deaths: b.deaths, moved: +moved[i].toFixed(2), pos: b.pos.toArray().map(v => +v.toFixed(2)) })),
    botMovedMin: Math.min(...moved), botMovedMax: Math.max(...moved), nan, maxStep,
    hudMode: document.querySelector('#mode-name').textContent,
    objective: document.querySelector('#objective-line').textContent,
    scoreCT: document.querySelector('#score-ct').textContent,
    scoreT: document.querySelector('#score-t').textContent,
  };
});

// wait a couple of real frames for HUD
await page.waitForTimeout(900);
out.hudTdm = await page.evaluate(() => ({
  mode: document.querySelector('#mode-name').textContent,
  objective: document.querySelector('#objective-line').textContent,
  scoreCT: document.querySelector('#score-ct').textContent,
  scoreT: document.querySelector('#score-t').textContent,
  clock: document.querySelector('#match-clock').textContent,
  ammo: document.querySelector('#ammo-value').textContent,
}));

// ── Industrial FFA 60s simulation ───────────────────────────────────────
out.ffa = await page.evaluate(async () => {
  const t = window.__tactical;
  t.startMatch({
    mapId: 'industrial', modeId: 'ffa', team: 'CT', botCount: 8, difficulty: 'Normal',
    scoreLimit: 15, timeLimit: 300, playerName: 'TestOp',
  });
  const g = t.game;
  const map = t.map;
  const start = g.bots.map(b => b.pos.clone());
  let nan = false;
  for (let i = 0; i < 1200; i++) {
    g.paused = false;
    g.update(1 / 20, { forward: i % 100 < 50, back: false, left: false, right: i % 60 < 30, crouch: false, walk: false, jumpPressed: false, fire: true, firePressed: i % 15 === 0, aim: false, reload: false, switchWeapon: false });
    for (const b of g.bots) if (!Number.isFinite(b.pos.x) || !Number.isFinite(b.pos.z)) nan = true;
    if (g.state !== 'playing') break;
  }
  g.paused = true;
  const moved = g.bots.map((b, i) => start[i].distanceTo(b.pos));
  const path = map.nav.findPath(map.spawns.CT[0], map.spawns.T[0]);
  const sp = { CT: map.spawns.CT.length, T: map.spawns.T.length, any: map.spawnsAny.length };
  return {
    state: g.state, map: g.config.mapId, mode: g.config.modeId, playerTeam: g.playerTeam,
    teamScores: g.teamScores, spawns: sp, navNodes: map.nav.nodes.length, navPath: path.length,
    player: { alive: t.player.alive, kills: t.player.kills, deaths: t.player.deaths, score: t.player.score },
    topScore: Math.max(...g.combatants().map(c => c.score || 0)),
    bots: g.bots.map((b, i) => ({ name: b.name, team: b.team, alive: b.alive, kills: b.kills, deaths: b.deaths, moved: +moved[i].toFixed(2), state: b.state })),
    nan,
    objective: document.querySelector('#objective-line').textContent,
  };
});

await page.waitForTimeout(1200);
out.hudFfa = await page.evaluate(() => ({
  mode: document.querySelector('#mode-name').textContent,
  objective: document.querySelector('#objective-line').textContent,
  map: document.querySelector('#radar-map').textContent,
  labelCT: document.querySelector('#hud-team-ct .team-label').textContent,
  labelT: document.querySelector('#hud-team-t .team-label').textContent,
  scoreCT: document.querySelector('#score-ct').textContent,
  scoreT: document.querySelector('#score-t').textContent,
}));

// ── FFA end-match path ──────────────────────────────────────────────────
out.ffaEnd = await page.evaluate(async () => {
  const t = window.__tactical;
  const g = t.game;
  g.paused = false;
  const top = g.combatants().slice().sort((a, b) => (b.score || 0) - (a.score || 0))[0];
  top.score = g.scoreLimit;
  const ended = g.checkScoreLimit();
  await new Promise(r => setTimeout(r, 100));
  return {
    ended, state: g.state,
    resultsVisible: !document.querySelector('#results-screen').classList.contains('hidden'),
    title: document.querySelector('#results-title').textContent,
    subtitle: document.querySelector('#results-subtitle').textContent,
    scoreLine: document.querySelector('#results-score').textContent,
    winner: g.lastResult?.winnerName, draw: g.lastResult?.draw, playerWon: g.lastResult?.playerWon,
  };
});

out.errors = errors;
console.log(JSON.stringify(out, null, 2));
await browser.close();

import { chromium } from '/tmp/opencode/node_modules/playwright-core/index.mjs';
const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome', args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 640, height: 400 } });
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.stack));
await page.goto('http://127.0.0.1:5174/', { waitUntil: 'load' });
await page.waitForTimeout(1200);
await page.evaluate(() => {
  const t = window.__tactical;
