  t.renderer.setPixelRatio(0.5); t.renderer.setSize(innerWidth, innerHeight); t.renderer.shadowMap.enabled = false;
});

async function navTrial(mapId) {
  return page.evaluate(async (mapId) => {
    const t = window.__tactical;
    t.startMatch({ mapId, modeId: 'ffa', team: 'CT', botCount: 4, difficulty: 'Normal', scoreLimit: 50, timeLimit: 300, playerName: 'NavTest' });
    const g = t.game;
    // Keep only one bot, and keep the player dead so there are no combat distractions.
    const bot = g.bots[0];
    g.bots = [bot];
    t.player.alive = false; t.player.respawnTimer = 1e9;
    const spawns = [...(t.map.spawns.CT || []), ...(t.map.spawns.T || []), ...(t.map.spawnsAny || [])];
    const trials = [];
    for (let s = 0; s < Math.min(4, spawns.length); s++) {
      const sp = spawns[(s * 3) % spawns.length];
      bot.reset(sp, 0);
      bot.spawnProtection = 1e9; // also keep it immune to any stray damage
      bot.thinkTimer = 0;
      const start = bot.pos.clone();
      let cumulative = 0, maxStep = 0;
      let prev = bot.pos.clone();
      const states = new Set();
      for (let i = 0; i < 600; i++) {
        const gs = g.state;
        g.state = 'playing';
        bot.update(1 / 20, g);
        g.state = gs;
        const step = bot.pos.distanceTo(prev);
        if (step > maxStep) maxStep = step;
        cumulative += step;
        prev.copy(bot.pos);
        states.add(bot.state);
      }
      trials.push({
        spawn: [sp.x, sp.z], end: bot.pos.toArray().map(v => +v.toFixed(2)),
        displacement: +bot.pos.distanceTo(start).toFixed(2),
        cumulative: +cumulative.toFixed(2), maxStep: +maxStep.toFixed(2),
        stuckCount: bot.stuckCount, states: [...states],
      });
    }
    return { map: t.map.id, nodes: t.map.nav.nodes.length, trials };
  }, mapId);
}

const out = {};
out.oldQuarter = await navTrial('old-quarter');
out.industrial = await navTrial('industrial');
out.errors = errors;
console.log(JSON.stringify(out, null, 2));
await browser.close();

