content.text:
import { chromium } from '/tmp/opencode/node_modules/playwright-core/index.mjs';
const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome', args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 640, height: 400 } });
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.stack));
await page.goto('http://127.0.0.1:5174/', { waitUntil: 'load' });
await page.waitForTimeout(1200);
await page.evaluate(() => {
  const t = window.__tactical;
  Object.assign(t.settings, { quality: 'low', shadows: 'off', renderScale: 0.5 });
  t.renderer.setPixelRatio(0.5); t.renderer.setSize(innerWidth, innerHeight); t.renderer.shadowMap.enabled = false;
});
const out = {};

out.spawnClearance = await page.evaluate(async () => {
  const physics = await import('/src/physics.js');
  const map = window.__tactical.map;
  const check = (arr) => arr.map(p => ({ p: [p.x, p.z], free: physics.isSpawnFree(map, p.x, p.z, 0.45) }));
  return {
    map: map.id,
    CT: check(map.spawns.CT), T: check(map.spawns.T), any: check(map.spawnsAny),
  };
});

// ── Old quarter TDM 60s simulation ──────────────────────────────────────
out.tdm = await page.evaluate(async () => {
  const t = window.__tactical;
  t.startMatch({
    mapId: 'old-quarter', modeId: 'tdm', team: 'CT', botCount: 8, difficulty: 'Normal',
    scoreLimit: 50, timeLimit: 300, playerName: 'TestOp',
  });
  const g = t.game;
  g.paused = true;
  const start = g.bots.map(b => b.pos.clone());
  let nan = false;
  let maxStep = 0;
  const prev = g.bots.map(b => b.pos.clone());
  for (let i = 0; i < 1200; i++) {
    g.paused = false;
    g.update(1 / 20, { forward: i % 120 < 60, back: false, left: i % 80 < 40, right: false, crouch: false, walk: false, jumpPressed: false, fire: true, firePressed: i % 20 === 0, aim: false, reload: false, switchWeapon: false });
    for (let j = 0; j < g.bots.length; j++) {
      const p = g.bots[j].pos;
      if (!Number.isFinite(p.x) || !Number.isFinite(p.y) || !Number.isFinite(p.z)) nan = true;
      const d = p.distanceTo(prev[j]); if (d > maxStep) maxStep = d;
      prev[j].copy(p);
    }
    if (g.state !== 'playing') break;
  }
  g.paused = true;
  const moved = g.bots.map((b, i) => start[i].distanceTo(b.pos));
  return {
    state: g.state, timeRemaining: Math.round(g.timeRemaining),
    playerTeam: g.playerTeam, teamScores: g.teamScores,
    player: { alive: t.player.alive, health: t.player.health, kills: t.player.kills, deaths: t.player.deaths, score: t.player.score, pos: t.player.pos.toArray() },
    bots: g.bots.map((b, i) => ({ name: b.name, team: b.team, state: b.state, alive: b.alive, kills: b.kills, deaths: b.deaths, moved: +moved[i].toFixed(2), pos: b.pos.toArray().map(v => +v.toFixed(2)) })),
    botMovedMin: Math.min(...moved), botMovedMax: Math.max(...moved), nan, maxStep,
    hudMode: document.querySelector('#mode-name').textContent,
    objective: document.querySelector('#objective-line').textContent,
    scoreCT: document.querySelector('#score-ct').textContent,
    scoreT: document.querySelector('#score-t').textContent,
  };
});

// wait a couple of real frames for HUD
await page.waitForTimeout(900);
out.hudTdm = await page.evaluate(() => ({
  mode: document.querySelector('#mode-name').textContent,
  objective: document.querySelector('#objective-line').textContent,
  scoreCT: document.querySelector('#score-ct').textContent,
  scoreT: document.querySelector('#score-t').textContent,
  clock: document.querySelector('#match-clock').textContent,
  ammo: document.querySelector('#ammo-value').textContent,
}));

// ── Industrial FFA 60s simulation ───────────────────────────────────────
out.ffa = await page.evaluate(async () => {
  const t = window.__tactical;
  t.startMatch({
    mapId: 'industrial', modeId: 'ffa', team: 'CT', botCount: 8, difficulty: 'Normal',
    scoreLimit: 15, timeLimit: 300, playerName: 'TestOp',
  });
  const g = t.game;
  const map = t.map;
  const start = g.bots.map(b => b.pos.clone());
  let nan = false;
  for (let i = 0; i < 1200; i++) {
    g.paused = false;
    g.update(1 / 20, { forward: i % 100 < 50, back: false, left: false, right: i % 60 < 30, crouch: false, walk: false, jumpPressed: false, fire: true, firePressed: i % 15 === 0, aim: false, reload: false, switchWeapon: false });
    for (const b of g.bots) if (!Number.isFinite(b.pos.x) || !Number.isFinite(b.pos.z)) nan = true;
    if (g.state !== 'playing') break;
  }
  g.paused = true;
  const moved = g.bots.map((b, i) => start[i].distanceTo(b.pos));
  const path = map.nav.findPath(map.spawns.CT[0], map.spawns.T[0]);
  const sp = { CT: map.spawns.CT.length, T: map.spawns.T.length, any: map.spawnsAny.length };
  return {
    state: g.state, map: g.config.mapId, mode: g.config.modeId, playerTeam: g.playerTeam,
    teamScores: g.teamScores, spawns: sp, navNodes: map.nav.nodes.length, navPath: path.length,
    player: { alive: t.player.alive, kills: t.player.kills, deaths: t.player.deaths, score: t.player.score },
    topScore: Math.max(...g.combatants().map(c => c.score || 0)),
    bots: g.bots.map((b, i) => ({ name: b.name, team: b.team, alive: b.alive, kills: b.kills, deaths: b.deaths, moved: +moved[i].toFixed(2), state: b.state })),
    nan,
    objective: document.querySelector('#objective-line').textContent,
  };
});

await page.waitForTimeout(1200);
out.hudFfa = await page.evaluate(() => ({
  mode: document.querySelector('#mode-name').textContent,
  objective: document.querySelector('#objective-line').textContent,
  map: document.querySelector('#radar-map').textContent,
  labelCT: document.querySelector('#hud-team-ct .team-label').textContent,
  labelT: document.querySelector('#hud-team-t .team-label').textContent,
  scoreCT: document.querySelector('#score-ct').textContent,
  scoreT: document.querySelector('#score-t').textContent,
}));

// ── FFA end-match path ──────────────────────────────────────────────────
out.ffaEnd = await page.evaluate(async () => {
  const t = window.__tactical;
  const g = t.game;
  g.paused = false;
  const top = g.combatants().slice().sort((a, b) => (b.score || 0) - (a.score || 0))[0];
  top.score = g.scoreLimit;
  const ended = g.checkScoreLimit();
  await new Promise(r => setTimeout(r, 100));
  return {
    ended, state: g.state,
    resultsVisible: !document.querySelector('#results-screen').classList.contains('hidden'),
    title: document.querySelector('#results-title').textContent,
    subtitle: document.querySelector('#results-subtitle').textContent,
    scoreLine: document.querySelector('#results-score').textContent,
    winner: g.lastResult?.winnerName, draw: g.lastResult?.draw, playerWon: g.lastResult?.playerWon,
  };
});

out.errors = errors;
console.log(JSON.stringify(out, null, 2));
await browser.close();

// Application entry point. Wires the renderer, menu, match systems and input together.
import * as THREE from 'three';
import {
  loadSettings, saveSettings, loadProfile, saveProfile,
  QUALITY_PRESETS, MAPS, MODES, clamp,
} from './config.js';
import { MaterialLibrary } from './materials.js';
import { buildMap } from './maps/index.js';
import { Player } from './player.js';
import { Game } from './game.js';
import { UI } from './ui.js';
import { ViewModel } from './viewmodel.js';
import { Effects } from './effects.js';
import { AudioSystem } from './audio.js';

const MENU_FOV = 58;

/* ── Core objects ──────────────────────────────────────────────────────── */
const canvas = document.querySelector('#game-canvas');

const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  powerPreference: 'high-performance',
});
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.06;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(MENU_FOV, window.innerWidth / window.innerHeight, 0.06, 420);
camera.rotation.order = 'YXZ';
scene.add(camera);

const settings = loadSettings();
const profile = loadProfile();
if (!profile.name || profile.name === 'Operator') profile.name = settings.name || 'Operator';
settings.name = profile.name;

const materials = new MaterialLibrary(renderer);
const effects = new Effects(scene);
const audio = new AudioSystem(settings);
const player = new Player();
const viewModel = new ViewModel(camera, materials.materials);
// Dedicated weapon light on its own render layer, so the view model stays readable
// without brightening the world around the player.
const viewLight = new THREE.PointLight(0xffdfb6, 4.2, 2.6, 2);
viewLight.position.set(0.24, 0.18, -0.18);
viewLight.layers.set(1);
camera.layers.enable(1);
viewModel.root.traverse((obj) => obj.layers.set(1));
camera.add(viewLight);

const ui = new UI({ settings, profile });
const game = new Game({ scene, player, world: null, effects, audio, materials: materials.materials, ui });
game.viewModel = viewModel;

let mapBuilder = null;
let currentConfig = null;
let menuAngle = 0.85;

/* ── Settings and renderer quality ─────────────────────────────────────── */
function deviceScale() {
  const preset = QUALITY_PRESETS[settings.quality] || QUALITY_PRESETS.high;
  const base = Math.min(window.devicePixelRatio || 1, preset.pixelRatio);
  return clamp(base * (settings.renderScale || 1), 0.5, 2);
}

function applyGraphics() {
  const preset = QUALITY_PRESETS[settings.quality] || QUALITY_PRESETS.high;
  renderer.setPixelRatio(deviceScale());
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.shadowMap.enabled = settings.shadows !== 'off';
  renderer.shadowMap.type = settings.shadows === 'high' ? THREE.PCFSoftShadowMap : THREE.PCFShadowMap;
  materials.setAnisotropy(preset.anisotropy);

  if (mapBuilder?.sun) {
    const sun = mapBuilder.sun;
    sun.castShadow = settings.shadows !== 'off';
    if (settings.shadows !== 'off') {
      const size = settings.shadows === 'high' ? 2048 : 1024;
      if (sun.shadow.mapSize.x !== size) {
        sun.shadow.mapSize.set(size, size);
        if (sun.shadow.map) {
          sun.shadow.map.dispose();
          sun.shadow.map = null;
        }
      }
    }
  }
  if (renderer.shadowMap.enabled) renderer.shadowMap.needsUpdate = true;
}

function setCameraFov(fov) {
  if (Math.abs(camera.fov - fov) > 0.01) {
    camera.fov = fov;
    camera.updateProjectionMatrix();
  }
}

function applySettings({ save = false } = {}) {
  audio.setSettings(settings);
  applyGraphics();
  ui.applyCrosshair();
  if (game.state !== 'playing') setCameraFov(MENU_FOV);
  if (save) saveSettings(settings);
}

/* ── Map lifecycle ─────────────────────────────────────────────────────── */
function loadMap(id) {
  const resolved = MAPS[id] ? id : 'old-quarter';
  if (mapBuilder?.id === resolved) {
    game.world = mapBuilder;
    applyGraphics();
    return mapBuilder;
  }
  if (mapBuilder) mapBuilder.root.removeFromParent();
  mapBuilder = buildMap(resolved, scene, materials);
  game.world = mapBuilder;
  if (mapBuilder.fog) {
    scene.fog = new THREE.Fog(mapBuilder.fog.color, mapBuilder.fog.near, mapBuilder.fog.far);
    scene.background = new THREE.Color(mapBuilder.fog.color);
  }
  menuAngle = 0.85;
  applyGraphics();
  return mapBuilder;
}

/* ── Menu camera ───────────────────────────────────────────────────────── */
function updateMenuCamera(dt) {
  if (!mapBuilder) return;
  const cine = mapBuilder.cinematic || { center: new THREE.Vector3(0, 1.5, 0), radius: 30, height: 16, speed: 0.03 };
  menuAngle += dt * (cine.speed || 0.03);
  const radius = Math.max(18, (cine.radius || 30) * 0.82);
  camera.position.set(
    cine.center.x + Math.cos(menuAngle) * radius,
    Math.max(16, (cine.height || 10) + 8),
    cine.center.z + Math.sin(menuAngle) * radius,
  );
  camera.lookAt(cine.center.x, cine.center.y + 1.5, cine.center.z);
  setCameraFov(MENU_FOV);
}

function syncPlayerCamera() {
  camera.position.copy(player.eyePosition());
  camera.rotation.set(player.pitch + player.recoilPitch, player.yaw + player.recoilYaw, 0, 'YXZ');
  setCameraFov(settings.fov - player.aimFactor * 10);
}

/* ── Match lifecycle ───────────────────────────────────────────────────── */
function normaliseConfig(config) {
  const mapId = MAPS[config.mapId] ? config.mapId : 'old-quarter';
  const modeId = MODES[config.modeId] ? config.modeId : 'tdm';
  return {
    mapId,
    modeId,
    team: config.team === 'T' ? 'T' : 'CT',
    botCount: clamp(Number(config.botCount) || 8, 1, 15),
    difficulty: ['Easy', 'Normal', 'Hard'].includes(config.difficulty) ? config.difficulty : 'Normal',
    scoreLimit: clamp(Number(config.scoreLimit) || 50, 5, 200),
    timeLimit: clamp(Number(config.timeLimit) || 300, 60, 1800),
    playerName: (config.playerName || profile.name || 'Operator').slice(0, 18),
  };
}

function prepareMatch(config) {
  const matchConfig = normaliseConfig(config);
  currentConfig = matchConfig;
  player.displayName = matchConfig.playerName;
  profile.name = matchConfig.playerName;
  settings.name = matchConfig.playerName;
  settings.mapId = matchConfig.mapId;
  settings.modeId = matchConfig.modeId;
  settings.teamPreference = matchConfig.team;
  settings.botCount = matchConfig.botCount;
  settings.difficulty = matchConfig.difficulty;
  settings.scoreLimit = matchConfig.scoreLimit;
  settings.timeLimit = matchConfig.timeLimit;
  saveSettings(settings);
  saveProfile(profile);

  if (game.state !== 'idle') game.stop();
  loadMap(matchConfig.mapId);
  ui.hidePause();
  ui.hideResults();
  ui.hideScoreboard();
  ui.closeModal();
  game.world = mapBuilder;
  game.start(matchConfig, mapBuilder);
  ui.showMatch(matchConfig);
  ui.updateProfileLine();
  viewModel.root.visible = true;
  setCameraFov(settings.fov);
  ui.setPointerHint(true);
  requestLock();
  return matchConfig;
}

function startMatch(config) {
  audio.unlock();
  prepareMatch(config);
  ui.announce('OPERATION STARTED', `${MAPS[currentConfig.mapId].name.toUpperCase()} · ${MODES[currentConfig.modeId].name.toUpperCase()}`, 2400);
}

function restartMatch() {
  if (!currentConfig) { exitToMenu(); return; }
  audio.unlock();
  ui.hideResults();
  ui.hidePause();
  if (game.state !== 'idle') game.stop();
  game.world = mapBuilder;
  game.start(currentConfig, mapBuilder);
  ui.showMatch(currentConfig);
  viewModel.root.visible = true;
  setCameraFov(settings.fov);
  requestLock();
  ui.announce('MATCH RESTARTED', `${MAPS[currentConfig.mapId].name.toUpperCase()}`, 1600);
}

function exitToMenu() {
  game.stop();
  clearInputState();
  document.exitPointerLock?.();
  ui.hidePause();
  ui.hideResults();
  ui.hideScoreboard();
  ui.setPointerHint(false);
  loadMap(settings.mapId);
  ui.showMenu();
  viewModel.root.visible = false;
  setCameraFov(MENU_FOV);
}

function pauseGame() {
  if (game.state !== 'playing' || game.paused) return;
  game.paused = true;
  clearInputState();
  ui.showPause(currentConfig);
  ui.setPointerHint(false);
  ui.hideScoreboard();
  if (document.pointerLockElement === canvas) document.exitPointerLock?.();
}

function resumeGame() {
  if (game.state !== 'playing') return;
  ui.hidePause();
  game.paused = false;
  requestLock();
}

function requestLock() {
  if (game.state !== 'playing' || game.paused || ui.modalOpen) return;
  const lock = canvas.requestPointerLock?.();
  if (lock?.catch) lock.catch(() => {});
}

function recordResult(result) {
  profile.matches = (profile.matches || 0) + 1;
  if (result.playerWon) profile.wins = (profile.wins || 0) + 1;
  profile.kills = (profile.kills || 0) + result.playerKills;
  profile.deaths = (profile.deaths || 0) + result.playerDeaths;
  profile.bestStreak = Math.max(profile.bestStreak || 0, player.streak || 0);
  saveProfile(profile);
  ui.profile = profile;
  ui.updateProfileLine();
}

/* ── Input ─────────────────────────────────────────────────────────────── */
const keys = Object.create(null);
let mouseDown = false;
let rightDown = false;
let firePressed = false;
let jumpPressed = false;
let reloadPressed = false;
let switchPressed = false;
let hadLock = false;

function clearInputState() {
  for (const key of Object.keys(keys)) keys[key] = false;
  mouseDown = false;
  rightDown = false;
  firePressed = false;
  jumpPressed = false;
  reloadPressed = false;
  switchPressed = false;
}

function switchWeapon(id) {
  if (game.state !== 'playing' || game.paused || ui.modalOpen) return;
  if (player.setWeapon(id)) viewModel.switchWeapon(id);
}

function buildInput() {
  const locked = document.pointerLockElement === canvas;
  const input = {
    forward: !!keys.KeyW,
    back: !!keys.KeyS,
    left: !!keys.KeyA,
    right: !!keys.KeyD,
    crouch: !!(keys.ControlLeft || keys.ControlRight),
    walk: !!(keys.ShiftLeft || keys.ShiftRight),
    jumpPressed,
    fire: mouseDown && locked,
    firePressed: firePressed && locked,
    aim: rightDown && locked,
    reload: reloadPressed,
    switchWeapon: switchPressed,
  };
  jumpPressed = false;
  firePressed = false;
  reloadPressed = false;
  switchPressed = false;
  return input;
}

document.addEventListener('keydown', (event) => {
  const playing = game.state === 'playing';
  if (playing && event.code === 'Tab') event.preventDefault();
  if (playing && event.code === 'Space') event.preventDefault();

  if (event.code === 'Escape') {
    if (ui.modalOpen) { ui.closeModal(); return; }
    if (playing && !game.paused) pauseGame();
    return;
  }
  if (!playing || game.paused || ui.modalOpen) return;

  if (event.code === 'Tab') {
    if (!event.repeat) ui.showScoreboard(game);
    return;
  }

  keys[event.code] = true;
  if (event.repeat) return;

  if (event.code === 'KeyR') reloadPressed = true;
  if (event.code === 'KeyQ') switchPressed = true;
  if (event.code === 'Space') jumpPressed = true;
  if (event.code === 'Digit1') switchWeapon('rifle');
  if (event.code === 'Digit2') switchWeapon('pistol');
});

document.addEventListener('keyup', (event) => {
  keys[event.code] = false;
  if (event.code === 'Tab') ui.hideScoreboard();
});

window.addEventListener('blur', clearInputState);

document.addEventListener('mousemove', (event) => {
  if (document.pointerLockElement !== canvas || game.state !== 'playing' || game.paused) return;
  const sensitivity = 0.0022 * (settings.sensitivity || 1);
  const invert = settings.invertY ? -1 : 1;
  player.yaw -= event.movementX * sensitivity;
  player.pitch = clamp(player.pitch - event.movementY * sensitivity * invert, -1.45, 1.45);
  viewModel.addSway(event.movementX, event.movementY);
});

document.addEventListener('mousedown', (event) => {
  audio.unlock();
  if (game.state !== 'playing' || game.paused || ui.modalOpen) return;
  if (event.button === 0) {
    if (document.pointerLockElement !== canvas) { requestLock(); return; }
    mouseDown = true;
    firePressed = true;
  } else if (event.button === 2) {
    rightDown = true;
  }
});

document.addEventListener('mouseup', (event) => {
  if (event.button === 0) mouseDown = false;
  if (event.button === 2) rightDown = false;
});

document.addEventListener('contextmenu', (event) => {
  if (event.target === canvas) event.preventDefault();
});

canvas.addEventListener('click', () => {
  audio.unlock();
  if (document.pointerLockElement !== canvas) requestLock();
});

canvas.addEventListener('wheel', (event) => {
  if (game.state !== 'playing' || game.paused || ui.modalOpen) return;
  event.preventDefault();
  switchWeapon(player.weaponId === 'rifle' ? 'pistol' : 'rifle');
}, { passive: false });

document.addEventListener('pointerlockchange', () => {
  const locked = document.pointerLockElement === canvas;
  if (locked) {
    hadLock = true;
    ui.setPointerHint(false);
  } else {
    ui.setPointerHint(game.state === 'playing' && !game.paused && !ui.modalOpen);
    if (hadLock && game.state === 'playing' && !game.paused && !ui.modalOpen) pauseGame();
  }
});

/* ── UI wiring ─────────────────────────────────────────────────────────── */
ui.onUiSound = () => { audio.unlock(); audio.uiClick(); };
ui.onStart = (config) => startMatch(config);
ui.onQuickPlay = () => startMatch({
  mapId: settings.mapId,
  modeId: settings.modeId,
  team: settings.teamPreference,
  botCount: settings.botCount,
  difficulty: settings.difficulty,
  scoreLimit: settings.scoreLimit,
  timeLimit: settings.timeLimit,
  playerName: profile.name,
});
ui.onResume = () => resumeGame();
ui.onRestart = () => restartMatch();
ui.onExit = () => exitToMenu();
ui.onPlayAgain = () => restartMatch();
ui.onChangeMatch = () => { exitToMenu(); ui.openSetup('CHANGE MATCH'); };
ui.onSettingsChange = (next, options = {}) => {
  Object.assign(settings, next);
  applySettings({ save: !!options.save });
  ui.updateMenuBriefing();
};
ui.onProfileSave = (nextProfile) => {
  if (nextProfile?.name) {
    profile.name = nextProfile.name;
    settings.name = nextProfile.name;
  }
  saveProfile(profile);
  saveSettings(settings);
  ui.updateProfileLine();
};
ui.onPreviewMap = (mapId) => {
  settings.mapId = mapId;
  if (game.state === 'idle') {
    loadMap(mapId);
    ui.updateMenuBriefing();
  }
};

game.on('start', () => {
  ui.setPointerHint(true);
});
game.on('kill', (data) => {
  ui.killFeed(data);
  if (data?.playerKill && data.headshot) ui.announce('HEADSHOT', 'CLEAN KILL', 900);
  if (data?.playerKill && player.streak === 3) ui.announce('DOMINATING', '3 KILL STREAK', 1300);
  if (data?.playerKill && player.streak === 5) ui.announce('UNSTOPPABLE', '5 KILL STREAK', 1500);
});
game.on('playerDamaged', (data) => ui.damage(data.direction, player.yaw));
game.on('playerKilled', () => {
  ui.announce('ELIMINATED', 'REDEPLOYING', 1500);
});
game.on('respawned', () => {
  ui.announce('REDEPLOYED', 'STAY SHARP', 900);
});
game.on('end', (result) => {
  recordResult(result);
  clearInputState();
  ui.showResults(result);
  ui.setPointerHint(false);
  document.exitPointerLock?.();
});

/* ── Resize ────────────────────────────────────────────────────────────── */
window.addEventListener('resize', () => {
  renderer.setPixelRatio(deviceScale());
  renderer.setSize(window.innerWidth, window.innerHeight);
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
});

/* ── Boot ──────────────────────────────────────────────────────────────── */
loadMap(settings.mapId);
ui.init();
applySettings();
viewModel.root.visible = false;
setCameraFov(MENU_FOV);
ui.updateProfileLine();
ui.updateMenuBriefing();
ui.showMenu();

/* ── Frame loop ────────────────────────────────────────────────────────── */
// Development/debug handle used by the automated browser checks.
window.__tactical = {
  game, player, ui, settings, profile, audio, effects,
  scene, camera, renderer, viewModel,
  startMatch, restartMatch, exitToMenu, pauseGame, resumeGame,
  get map() { return mapBuilder; },
};

const clock = new THREE.Clock();

function frame() {
  requestAnimationFrame(frame);
  const dt = Math.min(0.05, clock.getDelta());
  const playing = game.state === 'playing';
  viewModel.root.visible = playing;

  if (playing && !game.paused) {
    const input = buildInput();
    game.update(dt, input);
    syncPlayerCamera();
    viewModel.update(dt, {
      speed: Math.hypot(player.vel.x, player.vel.z),
      aiming: player.aiming,
      grounded: player.grounded,
      crouching: player.crouching,
    });
    effects.update(dt);
    ui.updateHUD(game, dt);
  } else if (!playing) {
    updateMenuCamera(dt);
    effects.update(dt);
  }

  renderer.render(scene, camera);
}

frame();

// DOM interface: main menu, match setup, settings, HUD, scoreboard, pause and results.
import * as THREE from 'three';
import { DEFAULT_SETTINGS, MAP_LIST, MODE_LIST, DIFFICULTY_LIST, MAPS, MODES, DIFFICULTIES, formatTime, clamp } from './config.js';
import { rayBlocked } from './physics.js';

const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

export class UI {
  constructor({ settings, profile }) {
    this.settings = settings;
    this.profile = profile;
    this.game = null;
    this.world = null;
    this.modalOpen = false;
    this.lastHudUpdate = 0;
    this.hintTimer = 0;
    this.respawnShown = false;
    this.killRows = [];
    this.radarCtx = $('#radar')?.getContext('2d');
    this.toastTimer = 0;
    this.announceTimer = 0;
    this.fpsFrames = 0;
    this.fpsLast = performance.now();
    this.onStart = () => {};
    this.onQuickPlay = () => {};
    this.onResume = () => {};
    this.onRestart = () => {};
    this.onExit = () => {};
    this.onPlayAgain = () => {};
    this.onChangeMatch = () => {};
    this.onSettingsChange = () => {};
    this.onProfileSave = () => {};
    this.onPreviewMap = () => {};
  }

  init() {
    this.updateMenuBriefing();
    this.updateProfileLine();
    $('#main-menu').addEventListener('click', (e) => {
      const btn = e.target.closest('button[data-action]');
      if (!btn) return;
      this.click();
      this.handleMenuAction(btn.dataset.action);
    });
    $$('.briefing-actions button[data-action]').forEach(btn => {
      btn.addEventListener('click', () => { this.click(); this.handleMenuAction(btn.dataset.action); });
    });
    $('#modal-root').addEventListener('click', (e) => {
      if (e.target.closest('[data-modal-close]')) this.closeModal();
    });
    $('#pause-screen').addEventListener('click', (e) => {
      const btn = e.target.closest('button[data-pause]');
      if (!btn) return;
      this.click();
      const action = btn.dataset.pause;
      if (action === 'resume') this.onResume();
      else if (action === 'settings') this.openSettings(true);
      else if (action === 'restart') this.onRestart();
      else if (action === 'exit') this.onExit();
    });
    $('#result-again').addEventListener('click', () => { this.click(); this.onPlayAgain(); });
    $('#result-change').addEventListener('click', () => { this.click(); this.onChangeMatch(); });
    $('#result-menu').addEventListener('click', () => { this.click(); this.onExit(); });
    document.addEventListener('fullscreenchange', () => {
      const b = $('#fullscreen-toggle');
      if (b) b.textContent = document.fullscreenElement ? 'EXIT FULLSCREEN' : 'ENTER FULLSCREEN';
    });
  }

  click() { this.onUiSound?.(); }

  handleMenuAction(action) {
    if (action === 'quick') { this.closeModal(); this.onQuickPlay(); }
    else if (action === 'offline') this.openSetup('PLAY OFFLINE');
    else if (action === 'create') this.openSetup('CREATE GAME');
    else if (action === 'servers') this.openServers();
    else if (action === 'settings') this.openSettings(false);
    else if (action === 'profile') this.openProfile();
    else if (action === 'credits') this.openCredits();
  }

  updateMenuBriefing() {
    const map = MAPS[this.settings.mapId] || MAPS['old-quarter'];
    const mode = MODES[this.settings.modeId] || MODES.tdm;
    const preview = $('#map-preview');
    preview?.classList.toggle('industrial', map.id === 'industrial');
    $('#briefing-map-id').textContent = map.name.toUpperCase();
    $('#briefing-title').innerHTML = map.id === 'industrial' ? 'Cold steel.<br /><span>Long shadows.</span>' : 'Fine dust.<br /><span>Short fuses.</span>';
    $('#briefing-desc').textContent = map.description;
    $('#briefing-subtitle').textContent = map.subtitle;
    $('#briefing-size').textContent = map.size.toUpperCase();
    $('#briefing-mode').textContent = mode.name.toUpperCase();
    $('#briefing-skill').textContent = (this.settings.difficulty || 'Normal').toUpperCase();
  }

  updateProfileLine() {
    const line = $('#menu-profile-line');
    if (line) line.textContent = `${(this.profile.name || 'OPERATOR').toUpperCase()} · ${this.profile.matches || 0} MATCHES · ${this.profile.wins || 0} WINS`;
    const nameEl = $('#hud-player-name');
    if (nameEl) nameEl.textContent = (this.profile.name || 'OPERATOR').toUpperCase();
  }

  /* ── Modal shell ───────────────────────────────────────────────────── */
  openModal(html, onReady) {
    const root = $('#modal-root');
    const card = $('#modal-card');
    card.innerHTML = html;
    root.classList.remove('hidden');
    this.modalOpen = true;
    card.querySelectorAll('[data-modal-close]').forEach(b => b.addEventListener('click', () => this.closeModal()));
    onReady?.(card);
    // Keep focus inside the dialog for keyboard users.
    setTimeout(() => card.querySelector('button, input, select')?.focus(), 30);
  }

  closeModal() {
    $('#modal-root').classList.add('hidden');
    this.modalOpen = false;
    $('#modal-card').innerHTML = '';
  }

  modalHeader(title, subtitle) {
    return `<div class="modal-head"><div><h2>${esc(title)}</h2><p>${subtitle}</p></div><button class="modal-close" data-modal-close>CLOSE ✕</button></div>`;
  }

  /* ── Match setup ───────────────────────────────────────────────────── */
  openSetup(title = 'PLAY OFFLINE') {
    const s = this.settings;
    const state = {
      mapId: s.mapId || 'old-quarter',
      modeId: s.modeId || 'tdm',
      team: s.teamPreference || 'CT',
      bots: clamp(+(s.botCount ?? 8), 1, 15),
      difficulty: s.difficulty || 'Normal',
      scoreLimit: +(s.scoreLimit ?? 50),
      timeLimit: +(s.timeLimit ?? 300),
    };
    const build = () => {
      const mode = MODES[state.modeId] || MODES.tdm;
      const mapChoices = MAP_LIST.map(m => `
        <button data-setup-map="${m.id}" class="${state.mapId === m.id ? 'active' : ''}">
          <div class="mini-map"><i></i><i></i><i></i><i></i></div>
          <b>${esc(m.name)}</b><small>${esc(m.description)}</small>
        </button>`).join('');
      const modeChoices = MODE_LIST.map(m => `<button data-setup-mode="${m.id}" class="${state.modeId === m.id ? 'active' : ''}">${esc(m.name.toUpperCase())}</button>`).join('');
      const diffChoices = DIFFICULTY_LIST.map(d => `<button data-setup-diff="${d}" class="${state.difficulty === d ? 'active' : ''}">${esc(d.toUpperCase())}</button>`).join('');
      const teamChoices = ['CT', 'T'].map(t => `<button data-setup-team="${t}" class="${state.team === t ? 'active' : ''}">${t === 'CT' ? 'COUNTER-TERRORISTS' : 'TERRORISTS'}</button>`).join('');
      const scoreOpts = [15, 25, 50, 75].map(n => `<option value="${n}" ${state.scoreLimit === n ? 'selected' : ''}>${n} kills</option>`).join('');
      const timeOpts = [[120, '2 minutes'], [300, '5 minutes'], [600, '10 minutes']].map(([v, l]) => `<option value="${v}" ${state.timeLimit === v ? 'selected' : ''}>${l}</option>`).join('');
      return `${this.modalHeader(title, 'ALL MATCHES RUN LOCALLY AGAINST BOTS · NO ACCOUNT REQUIRED')}
        <div class="form-grid">
          <div class="field full"><label>GAME MODE</label><div class="segmented">${modeChoices}</div><div class="field-note" style="margin-top:8px">${esc(mode.description)}</div></div>
          <div class="field full"><label>MAP</label><div class="map-choice">${mapChoices}</div></div>
          <div class="field"><label>BOTS <span id="bot-count-label">${state.bots}</span></label><input id="setup-bots" type="range" min="1" max="15" step="1" value="${state.bots}" /><div class="field-note" style="border:0;padding:0">${mode.teamBased ? 'Bots are split across both teams.' : 'Every bot is an independent rival.'}</div></div>
          <div class="field"><label>BOT DIFFICULTY</label><div class="segmented">${diffChoices}</div></div>
          <div class="field"><label>TEAM PREFERENCE</label><div class="segmented">${teamChoices}</div><div class="field-note" style="border:0;padding:0">Used in Team Deathmatch.</div></div>
          <div class="field"><label>SCORE LIMIT</label><select id="setup-score">${scoreOpts}</select></div>
          <div class="field"><label>MATCH TIME</label><select id="setup-time">${timeOpts}</select></div>
          <div class="field"><label>YOUR CALLSIGN</label><input id="setup-name" value="${esc(this.profile.name || 'Operator')}" maxlength="18" /></div>
        </div>
        <div class="modal-actions"><button class="btn" data-modal-close>CANCEL</button><button class="btn primary" id="setup-start">START MATCH</button></div>`;
    };

    const attach = (card) => {
      card.querySelectorAll('[data-setup-map]').forEach(b => b.addEventListener('click', () => {
        state.mapId = b.dataset.setupMap;
        card.querySelectorAll('[data-setup-map]').forEach(x => x.classList.toggle('active', x === b));
        this.onPreviewMap(state.mapId);
      }));
      card.querySelectorAll('[data-setup-mode]').forEach(b => b.addEventListener('click', () => {
        state.modeId = b.dataset.setupMode;
        this.refreshSetup(card, state, build);
      }));
      card.querySelectorAll('[data-setup-diff]').forEach(b => b.addEventListener('click', () => {
        state.difficulty = b.dataset.setupDiff;
        card.querySelectorAll('[data-setup-diff]').forEach(x => x.classList.toggle('active', x === b));
      }));
      card.querySelectorAll('[data-setup-team]').forEach(b => b.addEventListener('click', () => {
        state.team = b.dataset.setupTeam;
        card.querySelectorAll('[data-setup-team]').forEach(x => x.classList.toggle('active', x === b));
      }));
      const bots = $('#setup-bots', card);
      bots?.addEventListener('input', () => { state.bots = +bots.value; $('#bot-count-label', card).textContent = bots.value; });
      $('#setup-score', card)?.addEventListener('change', (e) => { state.scoreLimit = +e.target.value; });
      $('#setup-time', card)?.addEventListener('change', (e) => { state.timeLimit = +e.target.value; });
      $('#setup-start', card)?.addEventListener('click', () => {
        this.click();
        const name = ($('#setup-name', card)?.value || 'Operator').trim().slice(0, 18) || 'Operator';
        this.onProfileSave({ ...this.profile, name });
        this.profile.name = name;
        this.settings.name = name;
        this.settings.mapId = state.mapId;
        this.settings.modeId = state.modeId;
        this.settings.teamPreference = state.team;
        this.settings.botCount = state.bots;
        this.settings.difficulty = state.difficulty;
        this.settings.scoreLimit = state.scoreLimit;
        this.settings.timeLimit = state.timeLimit;
        this.onSettingsChange(this.settings, { save: true });
        this.closeModal();
        this.onStart({
          mapId: state.mapId,
          modeId: state.modeId,
          team: state.team,
          botCount: state.bots,
          difficulty: state.difficulty,
          scoreLimit: state.scoreLimit,
          timeLimit: state.timeLimit,
          playerName: name,
        });
      });
    };

    this.openModal(build(), attach);
  }

  refreshSetup(card, state, build) {
    const scroll = $('.modal-card')?.scrollTop || 0;
    card.innerHTML = build();
    card.querySelectorAll('[data-modal-close]').forEach(b => b.addEventListener('click', () => this.closeModal()));
    this.attachSetup(card, state, build);
    card.scrollTop = scroll;
  }

  // Re-attach after a re-render. Kept separate from the closure above.
  attachSetup(card, state, build) {
    card.querySelectorAll('[data-setup-map]').forEach(b => b.addEventListener('click', () => {
      state.mapId = b.dataset.setupMap;
      card.querySelectorAll('[data-setup-map]').forEach(x => x.classList.toggle('active', x === b));
      this.onPreviewMap(state.mapId);
    }));
    card.querySelectorAll('[data-setup-mode]').forEach(b => b.addEventListener('click', () => {
      state.modeId = b.dataset.setupMode;
      this.refreshSetup(card, state, build);
    }));
    card.querySelectorAll('[data-setup-diff]').forEach(b => b.addEventListener('click', () => {
      state.difficulty = b.dataset.setupDiff;
      card.querySelectorAll('[data-setup-diff]').forEach(x => x.classList.toggle('active', x === b));
    }));
    card.querySelectorAll('[data-setup-team]').forEach(b => b.addEventListener('click', () => {
      state.team = b.dataset.setupTeam;
      card.querySelectorAll('[data-setup-team]').forEach(x => x.classList.toggle('active', x === b));
    }));
    const bots = $('#setup-bots', card);
    bots?.addEventListener('input', () => { state.bots = +bots.value; $('#bot-count-label', card).textContent = bots.value; });
    $('#setup-score', card)?.addEventListener('change', (e) => { state.scoreLimit = +e.target.value; });
    $('#setup-time', card)?.addEventListener('change', (e) => { state.timeLimit = +e.target.value; });
    $('#setup-start', card)?.addEventListener('click', () => {
      this.click();
      const name = ($('#setup-name', card)?.value || 'Operator').trim().slice(0, 18) || 'Operator';
      this.profile.name = name;
      this.settings.name = name;
      this.settings.mapId = state.mapId;
      this.settings.modeId = state.modeId;
      this.settings.teamPreference = state.team;
      this.settings.botCount = state.bots;
      this.settings.difficulty = state.difficulty;
      this.settings.scoreLimit = state.scoreLimit;
      this.settings.timeLimit = state.timeLimit;
      this.onProfileSave(this.profile);
      this.onSettingsChange(this.settings, { save: true });
      this.closeModal();
      this.onStart({
        mapId: state.mapId, modeId: state.modeId, team: state.team, botCount: state.bots,
        difficulty: state.difficulty, scoreLimit: state.scoreLimit, timeLimit: state.timeLimit, playerName: name,
      });
    });
  }

  /* ── Settings ──────────────────────────────────────────────────────── */
  openSettings(fromPause = false) {
    const s = { ...this.settings };
    const mk = () => `${this.modalHeader('SETTINGS', 'CHANGES ARE SAVED ON THIS DEVICE')}
      <div class="settings-tabs"><button class="active" data-tab="controls">CONTROLS</button><button data-tab="audio">AUDIO</button><button data-tab="video">VIDEO</button><button data-tab="game">GAME</button></div>
