          <label class="field full">MUSIC & AMBIENCE<div class="range-row"><input id="set-music" type="range" min="0" max="1" step="0.05" value="${s.musicVolume}" /><output id="out-music">${Math.round(s.musicVolume * 100)}%</output></div></label>
