  applyCrosshair() {
    const ch = $('#crosshair');
    if (ch) ch.style.setProperty('--ch', this.settings.crosshairColor || '#dfe7d3');
    $('#fps-counter')?.classList.toggle('hidden', !this.settings.showFps);
  }

