    el.innerHTML = header + table;
    el.classList.remove('hidden');
  }

  hideScoreboard() { $('#scoreboard').classList.add('hidden'); }

  setPointerHint(visible) { $('#pointer-hint').classList.toggle('hidden', !visible); }

  toast(text, duration = 2600) {
