    el.textContent = text;
    el.classList.add('show');
    clearTimeout(this.toastTimer);
    this.toastTimer = setTimeout(() => el.classList.remove('show'), duration);
  }

  showLoading(show) { $('#loading').classList.toggle('hidden', !show); }
}

