import { chromium } from '/tmp/opencode/node_modules/playwright-core/index.mjs';
const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome', args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 640, height: 400 } });
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.stack));
await page.goto('http://127.0.0.1:5174/', { waitUntil: 'load' });
await page.waitForTimeout(1500);
await page.evaluate(() => {
  const t = window.__tactical;
  Object.assign(t.settings, { quality: 'low', shadows: 'off', renderScale: 0.5 });
  t.renderer.setPixelRatio(0.5); t.renderer.setSize(innerWidth, innerHeight); t.renderer.shadowMap.enabled = false;
});
const out = {};
for (const [mapId, modeId] of [['old-quarter','tdm'],['industrial','ffa'],['old-quarter','ffa'],['industrial','tdm']]) {
  out[`${mapId}:${modeId}`] = await page.evaluate(({ mapId, modeId }) => {
    const t = window.__tactical;
    t.startMatch({ mapId, modeId, team: 'CT', botCount: 15, difficulty: 'Normal', scoreLimit: 50, timeLimit: 300, playerName: 'SpawnTest' });
    const g = t.game, p = t.player;
    const center = { x: 0, z: 0 };
    const dir = (yaw, bot) => bot
      ? { x: Math.sin(yaw), z: Math.cos(yaw) }
      : { x: -Math.sin(yaw), z: -Math.cos(yaw) };
    const pdir = dir(p.yaw, false);
    const toCenter = { x: center.x - p.pos.x, z: center.z - p.pos.z };
    const len = Math.hypot(toCenter.x, toCenter.z);
    const playerFacingCenter = (pdir.x * toCenter.x + pdir.z * toCenter.z) / Math.max(1e-6, len);
    const botFacing = g.bots.map(b => {
      const d = dir(b.yaw, true);
      const tc = { x: -b.pos.x, z: -b.pos.z };
      const l = Math.hypot(tc.x, tc.z);
      return (d.x * tc.x + d.z * tc.z) / Math.max(1e-6, l);
    });
    let minDist = Infinity;
    const all = [p, ...g.bots];
    for (let i = 0; i < all.length; i++) for (let j = i + 1; j < all.length; j++) {
      minDist = Math.min(minDist, Math.hypot(all[i].pos.x - all[j].pos.x, all[i].pos.z - all[j].pos.z));
    }
    return {
      map: t.map.id, mode: g.mode.id, spawns: { CT: t.map.spawns.CT.length, T: t.map.spawns.T.length, any: t.map.spawnsAny.length },
      player: { pos: [p.pos.x, p.pos.z], yaw: p.yaw, playerFacingCenter: +playerFacingCenter.toFixed(2) },
      botsFacingCenterMin: +Math.min(...botFacing).toFixed(2),
      minSpawnDistance: +minDist.toFixed(2),
      botCount: g.bots.length,
    };
  }, { mapId, modeId });
}
out.errors = errors;
console.log(JSON.stringify(out, null, 2));
await browser.close();

