input.content:
import { chromium } from '/tmp/opencode/node_modules/playwright-core/index.mjs';

const PORT = process.argv[2] || '5174';
const BASE = `http://127.0.0.1:${PORT}/`;
const browser = await chromium.launch({
  executablePath: '/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome',
  args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox'],
});
const page = await browser.newPage({ viewport: { width: 800, height: 500 } });
const errors = [];
const failed = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.stack));
page.on('requestfailed', r => failed.push(r.url() + ' :: ' + r.failure()?.errorText));
page.on('response', r => { if (r.status() >= 400) failed.push(r.status() + ' ' + r.url()); });

const out = {};
await page.goto(BASE, { waitUntil: 'load' });
await page.waitForTimeout(2500);

out.boot = await page.evaluate(async () => {
  await document.fonts.ready;
  return {
    menuVisible: document.querySelector('#menu-screen').classList.contains('visible'),
    hudHidden: document.querySelector('#hud').classList.contains('hidden'),
    barlow: document.fonts.check('16px "Barlow Condensed"'),
    plex: document.fonts.check('16px "IBM Plex Mono"'),
    fontsStatus: document.fonts.status,
    tactical: !!window.__tactical,
    hasWebGL: !!window.__tactical?.renderer?.getContext?.(),
    map: window.__tactical?.map?.id,
    navNodes: window.__tactical?.map?.nav?.nodes?.length,
  };
});

// ── Menu actions and modals ──────────────────────────────────────────────
out.menu = {};
for (const action of ['offline', 'create', 'servers', 'settings', 'profile', 'credits']) {
  await page.click(`#main-menu button[data-action="${action}"]`);
  await page.waitForTimeout(180);
  out.menu[action] = await page.evaluate(() => ({
    modal: !document.querySelector('#modal-root').classList.contains('hidden'),
    title: document.querySelector('#modal-card h2')?.textContent?.trim(),
    length: document.querySelector('#modal-card').innerHTML.length,
  }));
  await page.keyboard.press('Escape');
  await page.waitForTimeout(100);
}

// ── Settings save, reset, persistence ───────────────────────────────────
await page.click('#main-menu button[data-action="settings"]');
await page.waitForTimeout(150);
await page.evaluate(() => {
  const set = (id, value) => {
    const el = document.querySelector(id);
    el.value = value;
    el.dispatchEvent(new Event('input', { bubbles: true }));
  };
  set('#set-sens', '1.45');
  set('#set-fov', '88');
  document.querySelector('#set-fps').checked = true;
  const fit = document.querySelector('#set-invert'); fit.checked = true;
});
await page.click('#settings-save');
await page.waitForTimeout(200);
out.settingsSave = await page.evaluate(() => ({
  sens: window.__tactical.settings.sensitivity,
  fov: window.__tactical.settings.fov,
  fps: window.__tactical.settings.showFps,
  invert: window.__tactical.settings.invertY,
  saved: JSON.parse(localStorage.getItem('tacticalfps.settings.v2')).sensitivity,
}));
await page.click('#main-menu button[data-action="settings"]');
await page.waitForTimeout(150);
await page.click('#settings-reset');
await page.waitForTimeout(250);
out.settingsReset = await page.evaluate(() => ({
  sens: window.__tactical.settings.sensitivity,
  fov: window.__tactical.settings.fov,
  fps: window.__tactical.settings.showFps,
  invert: window.__tactical.settings.invertY,
  modalOpen: !document.querySelector('#modal-root').classList.contains('hidden'),
  saved: JSON.parse(localStorage.getItem('tacticalfps.settings.v2')).sensitivity,
}));
await page.keyboard.press('Escape');
await page.waitForTimeout(100);

// ── Setup UI: FFA on Industrial ─────────────────────────────────────────
await page.click('#main-menu button[data-action="offline"]');
await page.waitForTimeout(200);
await page.click('#modal-card [data-setup-mode="ffa"]');
await page.waitForTimeout(250);
await page.click('#modal-card [data-setup-map="industrial"]');
await page.waitForTimeout(200);
await page.$eval('#setup-bots', (el) => { el.value = '5'; el.dispatchEvent(new Event('input', { bubbles: true })); });
await page.$eval('#setup-score', (el) => { el.value = '15'; el.dispatchEvent(new Event('change', { bubbles: true })); });
await page.$eval('#setup-name', (el) => { el.value = 'Verifier'; });
await page.click('#setup-start');
await page.waitForTimeout(800);
out.ffaStart = await page.evaluate(() => {
  const t = window.__tactical, g = t.game;
  g.paused = true;
  t.ui.lastHudUpdate = 0;
  t.ui.updateHUD(g, 0.1);
  t.ui.showScoreboard(g);
  const scoreboard = {
    hidden: document.querySelector('#scoreboard').classList.contains('hidden'),
    header: document.querySelector('#scoreboard h3')?.textContent?.replace(/\s+/g, ' ').trim(),
    firstHeader: document.querySelector('#scoreboard thead th')?.textContent,
    firstCell: document.querySelector('#scoreboard tbody td')?.textContent,
  };
  t.ui.hideScoreboard();
  return {
    state: g.state, mode: g.mode.id, map: g.config.mapId, playerTeam: g.playerTeam,
    bots: g.bots.length, scoreLimit: g.scoreLimit, timeLimit: g.timeLimit,
    hud: {
      mode: document.querySelector('#mode-name').textContent,
      objective: document.querySelector('#objective-line').textContent,
      ct: document.querySelector('#score-ct').textContent,
      t: document.querySelector('#score-t').textContent,
      labelCT: document.querySelector('#hud-team-ct .team-label').textContent,
      labelT: document.querySelector('#hud-team-t .team-label').textContent,
      map: document.querySelector('#radar-map').textContent,
    },
    name: t.profile.name, scoreboard,
    viewmodel: t.viewModel.weaponId, playerWeapon: t.player.weaponId,
  };
});

// ── Deterministic movement, collision, jump, crouch ────────────────────
out.movement = await page.evaluate(() => {
  const t = window.__tactical, p = t.player, g = t.game;
  g.paused = true;
  const world = g.world;
  const step = (input, n = 60) => {
    for (let i = 0; i < n; i++) {
      p.update(1 / 60, { world, input: { forward: false, back: false, left: false, right: false, crouch: false, walk: false, jumpPressed: false, fire: false, firePressed: false, aim: false, reload: false, switchWeapon: false, ...input }, game: g });
    }
  };
  // Clear lane in Old Quarter is not the current map; use current spawn as a clear point.
  p.reset({ x: 0, y: 0, z: 33.4 }, Math.PI); // face center (-z)
  p.spawnProtection = 0;
  const start = p.pos.clone();
  step({ forward: true }, 120);
  const movedForward = p.pos.distanceTo(start);

  // Wall collision: face the south perimeter (forward is -z at yaw 0; use yaw Math.PI to face +z wall).
  p.reset({ x: 0, y: 0, z: 32 }, 0);
  p.spawnProtection = 0;
  step({ forward: true }, 180);
  const wallZ = p.pos.z;

  // Jump.
  p.reset({ x: 0, y: 0, z: 0 }, 0);
  p.spawnProtection = 0;
  step({}, 10);
  const y0 = p.pos.y;
  step({ jumpPressed: true }, 1);
  let peak = p.pos.y;
  for (let i = 0; i < 90; i++) { step({}, 1); peak = Math.max(peak, p.pos.y); }
  const landed = p.grounded && p.pos.y <= y0 + 0.01;

  // Crouch eye height.
  p.reset({ x: 0, y: 0, z: 0 }, 0);
  const eyeStand = p.eyePosition().y;
  step({ crouch: true }, 30);
  const eyeCrouch = p.eyePosition().y;

  return { movedForward: +movedForward.toFixed(2), wallZ: +wallZ.toFixed(2), y0, peak: +peak.toFixed(2), landed, eyeStand: +eyeStand.toFixed(2), eyeCrouch: +eyeCrouch.toFixed(2), crouching: p.crouching };
});

// ── Weapon switch sync, reload, damage, death, respawn ──────────────────
out.combat = await page.evaluate(() => {
  const t = window.__tactical, p = t.player, g = t.game, vm = t.viewModel;
  g.paused = true;
  // Restore rifle through the normal public path.
  p.setWeapon('rifle');
  vm.switchWeapon('rifle');
  // Q toggle through the controller; main.js mirrors it to the view model.
  p.update(1 / 60, { world: g.world, input: { switchWeapon: true }, game: g });
  const qSwitch = { player: p.weaponId, vm: vm.weaponId };
  p.update(1 / 60, { world: g.world, input: { switchWeapon: true }, game: g });
  const qSwitchBack = { player: p.weaponId, vm: vm.weaponId };

  // Reload.
  p.ammo = 5; p.reserve = 100; p.reloading = false;
  p.update(1 / 60, { world: g.world, input: { reload: true }, game: g });
  for (let i = 0; i < 160; i++) p.update(1 / 60, { world: g.world, input: {}, game: g });
  const reload = { ammo: p.ammo, reserve: p.reserve, reloading: p.reloading };

  // Non-lethal damage (armour removed).
  p.health = 100; p.armor = 0; p.alive = true; p.spawnProtection = 0;
  const fakeBot = { name: 'TestBot', team: 'T', score: 0, kills: 0, pos: p.pos.clone() };
  g.damagePlayer(30, fakeBot, { headshot: false, weapon: 'CV-47' });
  const damaged = { health: p.health, alive: p.alive };

  // Lethal damage then deterministic respawn.
  p.health = 1; p.armor = 0;
  p.setWeapon('pistol'); vm.switchWeapon('pistol');
  g.damagePlayer(50, fakeBot, { headshot: false, weapon: 'CV-47' });
  const died = { alive: p.alive, deaths: p.deaths, health: p.health, vm: vm.weaponId };
  g.bots = []; // isolate respawn from stray bot fire during the loop
  for (let i = 0; i < 100; i++) g.update(1 / 20, {});
  const respawned = { alive: p.alive, health: p.health, weapon: p.weaponId, vm: vm.weaponId, deaths: p.deaths };
  return { qSwitch, qSwitchBack, reload, damaged, died, respawned };
});

// ── FFA scoring and results ─────────────────────────────────────────────
out.ffaScoring = await page.evaluate(() => {
  const t = window.__tactical, g = t.game, p = t.player;
  g.paused = true;
  g.state = 'playing';
  const bot = g.bots[0];
  bot.spawnProtection = 0; bot.alive = true; bot.health = 100;
  const before = { score: p.score, kills: p.kills, botDeaths: bot.deaths };
  g.damageBot(bot, 9999, p, true, 'CV-47');
  const after = { score: p.score, kills: p.kills, botDeaths: bot.deaths, botAlive: bot.alive };
  p.score = g.scoreLimit;
  const ended = g.checkScoreLimit();
  t.ui.lastHudUpdate = 0;
  t.ui.updateHUD(g, 0.1);
  return {
    before, after, ended, state: g.state, lastResult: {
      winner: g.lastResult?.winnerName, playerWon: g.lastResult?.playerWon, reason: g.lastResult?.reason,
    },
    results: {
      visible: !document.querySelector('#results-screen').classList.contains('hidden'),
      title: document.querySelector('#results-title').textContent,
      subtitle: document.querySelector('#results-subtitle').textContent,
      score: document.querySelector('#results-score').textContent,
      firstHeader: document.querySelector('#results-table thead th')?.textContent,
      firstCell: document.querySelector('#results-table tbody td')?.textContent,
    },
  };
});

// ── TDM scoring, scoreboard and match end ───────────────────────────────
out.tdm = await page.evaluate(() => {
  const t = window.__tactical;
  t.startMatch({ mapId: 'old-quarter', modeId: 'tdm', team: 'CT', botCount: 4, difficulty: 'Normal', scoreLimit: 5, timeLimit: 300, playerName: 'Verifier' });
  const g = t.game, p = t.player;
  g.paused = true;
  const enemy = g.bots.find(b => b.team === 'T');
  enemy.spawnProtection = 0;
  const before = { ...g.teamScores };
  g.damageBot(enemy, 9999, p, false, 'CV-47');
  const after = { ...g.teamScores, playerScore: p.score, playerKills: p.kills };
  t.ui.showScoreboard(g);
  const scoreboard = {
    header: document.querySelector('#scoreboard h3')?.textContent?.replace(/\s+/g, ' ').trim(),
    rows: document.querySelectorAll('#scoreboard tbody tr').length,
    firstHeader: document.querySelector('#scoreboard thead th')?.textContent,
  };
  t.ui.hideScoreboard();
  // Force the team score to the limit and verify the result flow.
  g.teamScores.CT = g.scoreLimit;
  g.checkScoreLimit();
  return {
    before, after, scoreboard, state: g.state,
    result: { winner: g.lastResult?.winnerName, playerWon: g.lastResult?.playerWon, reason: g.lastResult?.reason },
    resultsVisible: !document.querySelector('#results-screen').classList.contains('hidden'),
    resultsScore: document.querySelector('#results-score').textContent,
    resultsTitle: document.querySelector('#results-title').textContent,
  };
});

// ── Play again / change match / pause / resume / exit ───────────────────
out.flow = {};
await page.click('#result-again');
await page.waitForTimeout(400);
out.flow.again = await page.evaluate(() => ({
  state: window.__tactical.game.state,
  resultsHidden: document.querySelector('#results-screen').classList.contains('hidden'),
  hudVisible: !document.querySelector('#hud').classList.contains('hidden'),
  mode: window.__tactical.game.mode.id,
  vm: window.__tactical.viewModel.weaponId,
}));
await page.evaluate(() => window.__tactical.pauseGame());
await page.waitForTimeout(250);
out.flow.paused = await page.evaluate(() => ({
  paused: window.__tactical.game.paused,
  pauseVisible: !document.querySelector('#pause-screen').classList.contains('hidden'),
  subtitle: document.querySelector('#pause-subtitle').textContent,
}));
await page.click('#pause-screen button[data-pause="resume"]');
await page.waitForTimeout(300);
out.flow.resumed = await page.evaluate(() => ({
  paused: window.__tactical.game.paused,
  pauseHidden: document.querySelector('#pause-screen').classList.contains('hidden'),
}));
await page.evaluate(() => window.__tactical.pauseGame());
await page.waitForTimeout(200);
await page.click('#pause-screen button[data-pause="exit"]');
await page.waitForTimeout(500);
out.flow.exited = await page.evaluate(() => ({
  state: window.__tactical.game.state,
  menuVisible: document.querySelector('#menu-screen').classList.contains('visible'),
  hudHidden: document.querySelector('#hud').classList.contains('hidden'),
  map: window.__tactical.map.id,
}));

// ── Persistence across reload ──────────────────────────────────────────
await page.evaluate(() => {
  const t = window.__tactical;
  Object.assign(t.settings, { sensitivity: 1.33, fov: 84, showFps: true, crosshairColor: '#ff5500' });
  localStorage.setItem('tacticalfps.settings.v2', JSON.stringify(t.settings));
});
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(2000);
out.persistence = await page.evaluate(async () => {
  await document.fonts.ready;
  return {
    menu: document.querySelector('#menu-screen').classList.contains('visible'),
    sens: window.__tactical.settings.sensitivity,
    fov: window.__tactical.settings.fov,
    fps: window.__tactical.settings.showFps,
    crosshair: window.__tactical.settings.crosshairColor,
    crosshairVar: document.querySelector('#crosshair').style.getPropertyValue('--ch'),
    fonts: { barlow: document.fonts.check('16px "Barlow Condensed"'), plex: document.fonts.check('16px "IBM Plex Mono"') },
  };
});

out.errors = errors;
out.failedRequests = [...new Set(failed)];
console.log(JSON.stringify(out, null, 2));
await browser.close();

content.text:
  font-size: 8px; letter-spacing: 1.3px; color: #bcb39c; background: rgba(20, 21, 17, 0.62);
}
.build-chip i { width: 6px; height: 6px; border-radius: 50%; background: #8ca474; box-shadow: 0 0 7px #8ca474; }

.menu-body {
  position: absolute; left: 6.2%; right: 6.2%; top: 19.5%; bottom: 10.5%;
  display: grid; grid-template-columns: minmax(300px, 350px) minmax(420px, 640px);
  gap: clamp(28px, 5.2vw, 92px); align-items: center; z-index: 2;
}

.main-menu { display: flex; flex-direction: column; gap: 4px; max-width: 360px; }
