  display: grid; grid-template-columns: 34px 1fr 18px; align-items: center; gap: 10px;
  width: 100%; text-align: left; color: #ddd8c9;
  background: linear-gradient(90deg, rgba(109, 98, 74, 0.15), rgba(25, 27, 22, 0.2));
