  padding: 9px 12px 9px 10px; transition: 140ms ease;
  position: relative; overflow: hidden;
}
.main-menu button::after {
  content: ''; position: absolute; inset: 0; background: linear-gradient(90deg, rgba(213, 171, 100, 0.14), transparent 75%);
  opacity: 0; transition: 140ms;
}
.main-menu button:hover, .main-menu button:focus-visible {
  outline: none; color: #fff6e4; border-color: rgba(216, 173, 104, 0.62);
