  background: linear-gradient(90deg, rgba(167, 128, 69, 0.3), rgba(44, 41, 30, 0.35));
}
.main-menu button:hover::after, .main-menu button:focus-visible::after { opacity: 1; }
.main-menu button.primary { background: linear-gradient(90deg, rgba(177, 133, 68, 0.28), rgba(49, 43, 30, 0.3)); border-left-color: var(--amber); }
.main-menu .idx { font-size: 8px; letter-spacing: 0.5px; color: #7f7a6b; padding-left: 2px; }
.main-menu button:hover .idx { color: var(--amber); }
.main-menu b { display: block; font: 600 17px 'Barlow Condensed', sans-serif; letter-spacing: 1.35px; }
.main-menu small { display: block; font-size: 8.5px; letter-spacing: 0.15px; color: #8d897c; margin-top: 2px; }
