124:     let pool = [];
125:     if (!this.mode.teamBased) pool = [...(builder.spawns.CT || []), ...(builder.spawns.T || []), ...(builder.spawnsAny || [])];
126:     else if (builder.spawns[team]?.length) pool = builder.spawns[team];
127:     else pool = [...(builder.spawns.CT || []), ...(builder.spawns.T || [])];
128:     if (!pool.length) return new THREE.Vector3(0, 0, 0);
