130:     const others = this.combatants().filter(e => e !== self && e.alive);
131:     const enemies = others.filter(e => this.mode.teamBased ? e.team !== team : true);
132: 
133:     const entries = pool.map((p) => {
134:       let nearest = Infinity;
135:       for (const e of others) nearest = Math.min(nearest, Math.hypot(e.pos.x - p.x, e.pos.z - p.z));
136:       let score = 100 + Math.random() * 12;
137:       for (const e of enemies) score += Math.min(42, Math.hypot(e.pos.x - p.x, e.pos.z - p.z));
138:       return { p, nearest, score };
139:     });
