141:     // Prefer genuinely free spawn points. If the pool is exhausted, pick the
142:     // least crowded point instead of stacking combatants on top of each other.
143:     const clear = entries.filter(e => e.nearest >= 2.6);
144:     const ranked = (clear.length ? clear : entries.slice().sort((a, b) => b.nearest - a.nearest).slice(0, 3))
145:       .sort((a, b) => b.score - a.score);
146:     const chosen = ranked[0] || { p: pool[0], nearest: 0 };
147:     const spawn = chosen.p.clone();
148:     if (chosen.nearest > 2.0) {
149:       const jx = spawn.x + (Math.random() - 0.5) * 1.0;
150:       const jz = spawn.z + (Math.random() - 0.5) * 1.0;
151:       const minToOther = others.reduce((min, e) => Math.min(min, Math.hypot(e.pos.x - jx, e.pos.z - jz)), Infinity);
152:       if (minToOther >= 2.0 && isSpawnFree(this.world, jx, jz, 0.4)) {
153:         spawn.x = jx;
154:         spawn.z = jz;
155:       }
156:     }
