159:       // fall back to an arbitrary point that another combatant already occupies.
160:       const free = entries
161:         .filter(e => isSpawnFree(this.world, e.p.x, e.p.z, 0.4))
162:         .sort((a, b) => b.nearest - a.nearest);
163:       if (free.length) spawn.copy(free[0].p);
